71:       ballPath: [{ x: 50, y: server === 1 ? 90 : 10 }, { x: 45, y: 50 }],
72:       isGameWon: false,
73:       isSetWon: false,
74:       isMatchWon: false,
75:       server,
76:     };
77:   }
78: 
79:   // 2. Ace
80:   if (roll < dfChance + aceChance) {
