237: export function getRoundName(round: number, totalRounds: number): string {
238:   const remaining = totalRounds - round;
239:   if (remaining === 1) return 'Финал';
240:   if (remaining === 2) return '1/2 финала';
241:   if (remaining === 3) return '1/4 финала';
242:   if (remaining === 4) return '1/8 финала';
