44: export function generateTournamentDraw(
45:   template: Omit<Tournament, 'matches' | 'isCompleted' | 'currentRound' | 'championId' | 'runnerUpId'>,
46:   allPlayers: Player[],
47:   _isFirst: boolean = false
48: ): Tournament {
49:   const eligiblePlayers = allPlayers
50:     .filter((p) => p.tour === template.tour && !p.retired)
51:     .sort((a, b) => a.rank - b.rank);
52: 
53:   const drawSize = template.drawSize;
54:   const numRounds = Math.log2(drawSize);
55: 
56:   // Take top ranked players up to drawSize
57:   const tournamentPlayers = eligiblePlayers.slice(0, drawSize);
58: 
59:   // Standard Tennis Seeding Placement (Seed 1 at top, Seed 2 at bottom, Seeds 3-4 in opposite halves)
60:   const seededIndices = getStandardBracketSeeding(drawSize);
61:   const seededDraw: Player[] = new Array(drawSize);
62: 
63:   for (let slot = 0; slot < drawSize; slot++) {
64:     const playerIdx = seededIndices[slot];
65:     seededDraw[slot] = tournamentPlayers[playerIdx] || tournamentPlayers[slot % tournamentPlayers.length];
66:   }
67: 
68:   // Generate matches round by round
69:   let currentRoundSize = drawSize / 2;
70:   const roundMatchesMap: Map<number, Match[]> = new Map();
71: 
72:   for (let round = 0; round < numRounds; round++) {
73:     const roundMatches: Match[] = [];
74:     const isFirstRound = round === 0;
75:     const roundName = getRoundName(round, numRounds);
76: 
77:     for (let m = 0; m < currentRoundSize; m++) {
78:       const matchId = `${template.id}-r${round}-m${m}`;
79: 
80:       let p1Id: string | null = null;
81:       let p2Id: string | null = null;
82:       let s1: number | undefined = undefined;
83:       let s2: number | undefined = undefined;
84: 
85:       if (isFirstRound) {
86:         const p1 = seededDraw[m * 2];
87:         const p2 = seededDraw[m * 2 + 1];
88:         p1Id = p1 ? p1.id : null;
89:         p2Id = p2 ? p2.id : null;
90:         if (p1 && p1.rank <= 32) s1 = p1.rank;
91:         if (p2 && p2.rank <= 32) s2 = p2.rank;
