138: export function repairTournamentBracket(tournament: Tournament, allPlayers: Player[]): Tournament {
139:   const updatedTournament = JSON.parse(JSON.stringify(tournament)) as Tournament;
140:   const eligiblePlayers = allPlayers
141:     .filter((p) => p.tour === updatedTournament.tour && !p.retired)
142:     .sort((a, b) => a.rank - b.rank);
143: 
144:   const numRounds = Math.log2(updatedTournament.drawSize);
145: 
146:   // Group matches by round
147:   const roundMatchesMap = new Map<number, Match[]>();
148:   for (let r = 0; r < numRounds; r++) {
149:     roundMatchesMap.set(r, updatedTournament.matches.filter((m) => m.round === r));
150:   }
151: 
152:   // 1. Ensure all nextMatchId / nextMatchSlot links are completely valid
153:   for (let round = 0; round < numRounds - 1; round++) {
154:     const currMatches = roundMatchesMap.get(round) || [];
155:     const nextMatches = roundMatchesMap.get(round + 1) || [];
156: 
157:     for (let i = 0; i < currMatches.length; i++) {
158:       const targetNextMatch = nextMatches[Math.floor(i / 2)];
159:       if (targetNextMatch) {
160:         currMatches[i].nextMatchId = targetNextMatch.id;
161:         currMatches[i].nextMatchSlot = (i % 2 === 0 ? 1 : 2);
162:       }
163:     }
164:   }
165: 
166:   // 2. Fix missing players in Round 0
167:   const r0Matches = roundMatchesMap.get(0) || [];
168:   const assignedPlayerIds = new Set<string>();
169:   r0Matches.forEach((m) => {
170:     if (m.player1Id) assignedPlayerIds.add(m.player1Id);
171:     if (m.player2Id) assignedPlayerIds.add(m.player2Id);
172:   });
173: 
174:   const unassignedPlayers = eligiblePlayers.filter((p) => !assignedPlayerIds.has(p.id));
175:   let unassignedIdx = 0;
176: 
177:   r0Matches.forEach((m) => {
178:     if (!m.player1Id && unassignedIdx < unassignedPlayers.length) {
179:       m.player1Id = unassignedPlayers[unassignedIdx++].id;
180:       const pObj = allPlayers.find((p) => p.id === m.player1Id);
181:       if (pObj && pObj.rank <= 32) m.seed1 = pObj.rank;
182:     }
183:     if (!m.player2Id && unassignedIdx < unassignedPlayers.length) {
184:       m.player2Id = unassignedPlayers[unassignedIdx++].id;
185:       const pObj = allPlayers.find((p) => p.id === m.player2Id);
186:       if (pObj && pObj.rank <= 32) m.seed2 = pObj.rank;
187:     }
188:   });
189: 
190:   // 3. Propagate completed match winners forward to next round matches
191:   for (let round = 0; round < numRounds - 1; round++) {
192:     const currMatches = roundMatchesMap.get(round) || [];
193:     for (const match of currMatches) {
194:       if (match.isCompleted && match.winnerId && match.nextMatchId) {
195:         const nextMatch = updatedTournament.matches.find((m) => m.id === match.nextMatchId);
196:         if (nextMatch) {
197:           if (match.nextMatchSlot === 1) {
198:             nextMatch.player1Id = match.winnerId;
199:             const pObj = allPlayers.find((p) => p.id === match.winnerId);
200:             if (pObj && pObj.rank <= 32) nextMatch.seed1 = pObj.rank;
201:           } else {
202:             nextMatch.player2Id = match.winnerId;
203:             const pObj = allPlayers.find((p) => p.id === match.winnerId);
204:             if (pObj && pObj.rank <= 32) nextMatch.seed2 = pObj.rank;
205:           }
206:         }
207:       }
208:     }
209:   }
210: 
211:   // 4. Check if final completed
212:   const finalMatch = updatedTournament.matches.find((m) => m.round === numRounds - 1);
213:   if (finalMatch && finalMatch.isCompleted && finalMatch.winnerId) {
214:     updatedTournament.isCompleted = true;
215:     updatedTournament.championId = finalMatch.winnerId;
216:     const loserId = finalMatch.player1Id === finalMatch.winnerId ? finalMatch.player2Id : finalMatch.player1Id;
217:     if (loserId) updatedTournament.runnerUpId = loserId;
218:   }
219: 
220:   return updatedTournament;
221: }
