313: export function finalizeTournamentAndDistributePoints(
314:   tournament: Tournament,
315:   players: Player[]
316: ): Player[] {
317:   const pointsMap = new Map<string, { points: number; prize: number; wonTitle: boolean }>();
318: 
319:   tournament.matches.forEach((m) => {
320:     if (m.isCompleted && m.player1Id && m.player2Id) {
321:       const loserId = m.winnerId === m.player1Id ? m.player2Id : m.player1Id;
322:       const isWinner = m.winnerId;
323: 
324:       let roundPoints = 0;
325:       let roundPrize = 0;
326: 
327:       if (m.roundName === 'Финал') {
328:         if (isWinner) {
329:           pointsMap.set(isWinner, {
330:             points: tournament.pointsWinner,
331:             prize: Math.round(tournament.prizeMoneyPool * 0.22),
332:             wonTitle: true,
333:           });
334:         }
335:         if (loserId) {
336:           pointsMap.set(loserId, {
337:             points: tournament.pointsFinalist,
338:             prize: Math.round(tournament.prizeMoneyPool * 0.12),
339:             wonTitle: false,
340:           });
341:         }
342:       } else if (m.roundName === '1/2 финала' && loserId && !pointsMap.has(loserId)) {
343:         roundPoints = tournament.pointsSemi;
344:         roundPrize = Math.round(tournament.prizeMoneyPool * 0.06);
345:         pointsMap.set(loserId, { points: roundPoints, prize: roundPrize, wonTitle: false });
346:       } else if (m.roundName === '1/4 финала' && loserId && !pointsMap.has(loserId)) {
347:         roundPoints = tournament.pointsQuarter;
348:         roundPrize = Math.round(tournament.prizeMoneyPool * 0.035);
349:         pointsMap.set(loserId, { points: roundPoints, prize: roundPrize, wonTitle: false });
350:       } else if (m.roundName === '1/8 финала' && loserId && !pointsMap.has(loserId)) {
351:         roundPoints = tournament.pointsR16;
352:         roundPrize = Math.round(tournament.prizeMoneyPool * 0.018);
353:         pointsMap.set(loserId, { points: roundPoints, prize: roundPrize, wonTitle: false });
354:       } else if (m.roundName === '1/16 финала' && loserId && !pointsMap.has(loserId)) {
355:         roundPoints = tournament.pointsR32;
356:         roundPrize = Math.round(tournament.prizeMoneyPool * 0.009);
357:         pointsMap.set(loserId, { points: roundPoints, prize: roundPrize, wonTitle: false });
358:       } else if (m.roundName === '1/32 финала' && loserId && !pointsMap.has(loserId)) {
359:         roundPoints = tournament.pointsR64;
360:         roundPrize = Math.round(tournament.prizeMoneyPool * 0.004);
361:         pointsMap.set(loserId, { points: roundPoints, prize: roundPrize, wonTitle: false });
362:       }
363:     }
364:   });
365: 
366:   const updatedPlayers = players.map((p) => {
367:     if (p.tour !== tournament.tour) return p;
368: 
369:     const tourneyPointsHistory = p.tournamentPoints || {};
370:     // Defended points = points earned at this specific tournament in the previous season edition
371:     const defendedPoints = tourneyPointsHistory[tournament.id] || 0;
372: 
373:     let earnedPoints = 0;
374:     let prize = 0;
375:     let wonTitle = false;
376: 
377:     if (pointsMap.has(p.id)) {
378:       const award = pointsMap.get(p.id)!;
379:       earnedPoints = award.points;
380:       prize = award.prize;
381:       wonTitle = award.wonTitle;
382:     } else {
383:       const playedInTournament = tournament.matches.some(
384:         (m) => m.player1Id === p.id || m.player2Id === p.id
385:       );
386:       if (playedInTournament) {
387:         earnedPoints = tournament.pointsR128 || tournament.pointsR64 || 0;
388:       }
389:     }
390: 
391:     const updatedTourneyPoints = {
392:       ...tourneyPointsHistory,
393:       [tournament.id]: earnedPoints,
394:     };
395: 
396:     const netPointsChange = earnedPoints - defendedPoints;
397:     const newPoints = Math.max(0, p.points + netPointsChange);
398: 
399:     return {
400:       ...p,
401:       previousPoints: p.points,
402:       points: newPoints,
403:       tournamentPoints: updatedTourneyPoints,
404:       prizeMoney: p.prizeMoney + prize,
405:       titles: wonTitle ? p.titles + 1 : p.titles,
406:       careerTitles: wonTitle ? p.careerTitles + 1 : p.careerTitles,
407:       grandSlams: wonTitle && tournament.category === 'Grand Slam' ? p.grandSlams + 1 : p.grandSlams,
408:     };
409:   });
410: 
411:   return recalculateRankings(updatedPlayers);
412: }
