414: export function recalculateRankings(players: Player[]): Player[] {
415:   const atp = players.filter((p) => p.tour === 'ATP' && !p.retired);
416:   const wta = players.filter((p) => p.tour === 'WTA' && !p.retired);
417:   const retired = players.filter((p) => p.retired);
418: 
419:   const sortTour = (list: Player[]) => {
420:     list.sort((a, b) => b.points - a.points || a.rank - b.rank);
421:     return list.map((p, idx) => ({
422:       ...p,
423:       previousRank: p.rank,
424:       rank: idx + 1,
425:     }));
426:   };
427: 
428:   const rankedAtp = sortTour(atp);
429:   const rankedWta = sortTour(wta);
430: 
431:   return [...rankedAtp, ...rankedWta, ...retired];
432: }
