434: export function simulateEntireTournament(
435:   tournament: Tournament,
436:   players: Player[]
437: ): { completedTournament: Tournament; updatedPlayers: Player[] } {
438:   let currTournament = JSON.parse(JSON.stringify(tournament)) as Tournament;
439:   let currPlayers = [...players];
440: 
441:   const totalRounds = Math.log2(currTournament.drawSize);
442: 
443:   for (let r = 0; r < totalRounds; r++) {
444:     const roundMatches = currTournament.matches.filter((m) => m.round === r && !m.isCompleted);
445:     for (const match of roundMatches) {
446:       if (match.player1Id && match.player2Id) {
447:         const p1 = currPlayers.find((p) => p.id === match.player1Id);
448:         const p2 = currPlayers.find((p) => p.id === match.player2Id);
449: 
450:         if (p1 && p2) {
451:           const sim = simulateFullMatch(p1, p2, currTournament.surface, currTournament.setsToWin);
452:           match.score = sim.score;
453:           const adv = advanceTournamentMatch(currTournament, match.id, sim.winnerId, currPlayers);
454:           currTournament = adv.updatedTournament;
455:           currPlayers = adv.updatedPlayers;
456:         }
457:       }
458:     }
459:   }
460: 
461:   currPlayers = finalizeTournamentAndDistributePoints(currTournament, currPlayers);
462:   return { completedTournament: currTournament, updatedPlayers: currPlayers };
463: }

