export function repairTournamentBracket(tournament: Tournament, allPlayers: Player[]): Tournament {
  const totalRounds = getBracketRoundCount(tournament.drawSize);
  const bracketSize = getBracketSize(tournament.drawSize);
  const hasValidShape = Array.from({ length: totalRounds }, (_, round) => {
    const expectedCount = bracketSize / (2 ** (round + 1));
    return tournament.matches.filter((match) => match.round === round).length === expectedCount;
  }).every(Boolean);

  if (!hasValidShape) {
    const eligiblePlayers = allPlayers
      .filter((player) => player.tour === tournament.tour && !player.retired)
      .sort((a, b) => a.rank - b.rank);
    const fresh = generateTournamentDraw(tournament, allPlayers);
    const oldFirstRound = tournament.matches
      .filter((match) => match.round === 0)
      .sort((a, b) => Number(a.id.split('-m').pop()) - Number(b.id.split('-m').pop()));
    const assigned = new Set<string>();

    // Keep the existing draw order where possible, then fill newly required bye slots.
    for (const oldMatch of oldFirstRound) {
      const newMatch = fresh.matches.find((match) => match.id === oldMatch.id);
      if (!newMatch) continue;
      for (const [slot, playerId] of [[1, oldMatch.player1Id], [2, oldMatch.player2Id]] as const) {
        if (!playerId || assigned.has(playerId) || !eligiblePlayers.some((player) => player.id === playerId)) continue;
        if (slot === 1) newMatch.player1Id = playerId;
        else newMatch.player2Id = playerId;
        assigned.add(playerId);
      }
      const getSeed = (playerId: string | null, seed: number | undefined) =>
        playerId ? (seed || allPlayers.find((player) => player.id === playerId)?.rank) : undefined;
      newMatch.seed1 = getSeed(newMatch.player1Id, oldMatch.seed1);
      newMatch.seed2 = getSeed(newMatch.player2Id, oldMatch.seed2);
      if (
        oldMatch.isCompleted && oldMatch.player1Id && oldMatch.player2Id &&
        oldMatch.winnerId && [newMatch.player1Id, newMatch.player2Id].includes(oldMatch.winnerId)
      ) {
        newMatch.isCompleted = true;
        newMatch.winnerId = oldMatch.winnerId;
        newMatch.score = oldMatch.score;
      }
    }

    const missingPlayers = eligiblePlayers
      .filter((player) => !assigned.has(player.id))
      .slice(0, Math.max(0, tournament.drawSize - assigned.size));
    let nextPlayer = 0;
    fresh.matches.filter((match) => match.round === 0).forEach((match) => {
      if (!match.player1Id && nextPlayer < missingPlayers.length) match.player1Id = missingPlayers[nextPlayer++].id;
      if (!match.player2Id && nextPlayer < missingPlayers.length) match.player2Id = missingPlayers[nextPlayer++].id;
    });

    // Only keep later results if the repaired bracket still gives the match the same players.
    resolveBracketByes(fresh);
    for (let round = 1; round < totalRounds; round++) {
      for (const rebuiltMatch of fresh.matches.filter((match) => match.round === round)) {
        const oldMatch = tournament.matches.find((match) => match.id === rebuiltMatch.id);
        if (
          oldMatch?.isCompleted && oldMatch.winnerId &&
          oldMatch.player1Id === rebuiltMatch.player1Id && oldMatch.player2Id === rebuiltMatch.player2Id &&
          rebuiltMatch.player1Id && rebuiltMatch.player2Id
        ) {
          rebuiltMatch.isCompleted = true;
          rebuiltMatch.winnerId = oldMatch.winnerId;
          rebuiltMatch.score = oldMatch.score;
        }
      }
      resolveBracketByes(fresh);
    }
    return fresh;
  }

  const updatedTournament = JSON.parse(JSON.stringify(tournament)) as Tournament;
  const eligiblePlayers = allPlayers
    .filter((player) => player.tour === updatedTournament.tour && !player.retired)
    .sort((a, b) => a.rank - b.rank);
  const firstRound = updatedTournament.matches.filter((match) => match.round === 0);
  const assignedPlayerIds = new Set(firstRound.flatMap((match) => [match.player1Id, match.player2Id].filter(Boolean) as string[]));
  const unassignedPlayers = eligiblePlayers.filter((player) => !assignedPlayerIds.has(player.id));
  let nextPlayer = 0;

  firstRound.forEach((match) => {
    if (!match.player1Id && nextPlayer < unassignedPlayers.length) match.player1Id = unassignedPlayers[nextPlayer++].id;
    if (!match.player2Id && nextPlayer < unassignedPlayers.length) match.player2Id = unassignedPlayers[nextPlayer++].id;
  });

  for (let round = 0; round < totalRounds - 1; round++) {
    const currentMatches = updatedTournament.matches.filter((match) => match.round === round);
    const nextMatches = updatedTournament.matches.filter((match) => match.round === round + 1);
    currentMatches.forEach((match, index) => {
      match.nextMatchId = nextMatches[Math.floor(index / 2)].id;
      match.nextMatchSlot = index % 2 === 0 ? 1 : 2;
    });
  }
  resolveBracketByes(updatedTournament);
  return updatedTournament;
}

