127:   _isFirst: boolean = false
128: ): Tournament {
129:   const eligiblePlayers = allPlayers
130:     .filter((p) => p.tour === template.tour && !p.retired)
131:     .sort((a, b) => a.rank - b.rank);
132:   const tournamentPlayers = eligiblePlayers.slice(0, template.drawSize);
133:   const seededIndices = getStandardBracketSeeding(template.drawSize);
134:   const seededDraw = new Array<Player | undefined>(getBracketSize(template.drawSize));
