150: export function repairTournamentBracket(tournament: Tournament, allPlayers: Player[]): Tournament {
151:   const totalRounds = getBracketRoundCount(tournament.drawSize);
152:   const bracketSize = getBracketSize(tournament.drawSize);
153:   const hasValidShape = Array.from({ length: totalRounds }, (_, round) => {
154:     const expectedCount = bracketSize / (2 ** (round + 1));
155:     return tournament.matches.filter((match) => match.round === round).length === expectedCount;
156:   }).every(Boolean);
157: 
158:   if (!hasValidShape) {
159:     const eligiblePlayers = allPlayers
160:       .filter((player) => player.tour === tournament.tour && !player.retired)
161:       .sort((a, b) => a.rank - b.rank);
162:     const fresh = generateTournamentDraw(tournament, allPlayers);
163:     const oldFirstRound = tournament.matches
164:       .filter((match) => match.round === 0)
165:       .sort((a, b) => Number(a.id.split('-m').pop()) - Number(b.id.split('-m').pop()));
166:     const assigned = new Set<string>();
167: 
168:     // Keep the existing draw order where possible, then fill newly required bye slots.
169:     for (const oldMatch of oldFirstRound) {
170:       const newMatch = fresh.matches.find((match) => match.id === oldMatch.id);
171:       if (!newMatch) continue;
172:       for (const [slot, playerId] of [[1, oldMatch.player1Id], [2, oldMatch.player2Id]] as const) {
173:         if (!playerId || assigned.has(playerId) || !eligiblePlayers.some((player) => player.id === playerId)) continue;
174:         if (slot === 1) newMatch.player1Id = playerId;
175:         else newMatch.player2Id = playerId;
176:         assigned.add(playerId);
177:       }
178:       const getSeed = (playerId: string | null, seed: number | undefined) =>
179:         playerId ? (seed || allPlayers.find((player) => player.id === playerId)?.rank) : undefined;
180:       newMatch.seed1 = getSeed(newMatch.player1Id, oldMatch.seed1);
181:       newMatch.seed2 = getSeed(newMatch.player2Id, oldMatch.seed2);
182:       if (
183:         oldMatch.isCompleted && oldMatch.player1Id && oldMatch.player2Id &&
184:         oldMatch.winnerId && [newMatch.player1Id, newMatch.player2Id].includes(oldMatch.winnerId)
185:       ) {
186:         newMatch.isCompleted = true;
187:         newMatch.winnerId = oldMatch.winnerId;
188:         newMatch.score = oldMatch.score;
189:       }
190:     }
191: 
192:     const missingPlayers = eligiblePlayers
193:       .filter((player) => !assigned.has(player.id))
194:       .slice(0, Math.max(0, tournament.drawSize - assigned.size));
195:     let nextPlayer = 0;
196:     fresh.matches.filter((match) => match.round === 0).forEach((match) => {
197:       if (!match.player1Id && nextPlayer < missingPlayers.length) match.player1Id = missingPlayers[nextPlayer++].id;
198:       if (!match.player2Id && nextPlayer < missingPlayers.length) match.player2Id = missingPlayers[nextPlayer++].id;
199:     });
200: 
201:     // Only keep later results if the repaired bracket still gives the match the same players.
202:     resolveBracketByes(fresh);
203:     for (let round = 1; round < totalRounds; round++) {
204:       for (const rebuiltMatch of fresh.matches.filter((match) => match.round === round)) {
205:         const oldMatch = tournament.matches.find((match) => match.id === rebuiltMatch.id);
206:         if (
207:           oldMatch?.isCompleted && oldMatch.winnerId &&
208:           oldMatch.player1Id === rebuiltMatch.player1Id && oldMatch.player2Id === rebuiltMatch.player2Id &&
209:           rebuiltMatch.player1Id && rebuiltMatch.player2Id
210:         ) {
211:           rebuiltMatch.isCompleted = true;
212:           rebuiltMatch.winnerId = oldMatch.winnerId;
213:           rebuiltMatch.score = oldMatch.score;
214:         }
215:       }
216:       resolveBracketByes(fresh);
217:     }
218:     return fresh;
219:   }
220: 
221:   const updatedTournament = JSON.parse(JSON.stringify(tournament)) as Tournament;
222:   const eligiblePlayers = allPlayers
223:     .filter((player) => player.tour === updatedTournament.tour && !player.retired)
224:     .sort((a, b) => a.rank - b.rank);
225:   const firstRound = updatedTournament.matches.filter((match) => match.round === 0);
226:   const assignedPlayerIds = new Set(firstRound.flatMap((match) => [match.player1Id, match.player2Id].filter(Boolean) as string[]));
227:   const unassignedPlayers = eligiblePlayers.filter((player) => !assignedPlayerIds.has(player.id));
228:   let nextPlayer = 0;
229: 
230:   firstRound.forEach((match) => {
231:     if (!match.player1Id && nextPlayer < unassignedPlayers.length) match.player1Id = unassignedPlayers[nextPlayer++].id;
232:     if (!match.player2Id && nextPlayer < unassignedPlayers.length) match.player2Id = unassignedPlayers[nextPlayer++].id;
233:   });
234: 
235:   for (let round = 0; round < totalRounds - 1; round++) {
236:     const currentMatches = updatedTournament.matches.filter((match) => match.round === round);
237:     const nextMatches = updatedTournament.matches.filter((match) => match.round === round + 1);
238:     currentMatches.forEach((match, index) => {
239:       match.nextMatchId = nextMatches[Math.floor(index / 2)].id;
240:       match.nextMatchSlot = index % 2 === 0 ? 1 : 2;
241:     });
242:   }
243:   resolveBracketByes(updatedTournament);
244:   return updatedTournament;
245: }
