276: export function advanceTournamentMatch(
277:   tournament: Tournament,
278:   matchId: string,
279:   winnerId: string,
280:   players: Player[]
281: ): { updatedTournament: Tournament; updatedPlayers: Player[] } {
282:   const updatedTournament = JSON.parse(JSON.stringify(tournament)) as Tournament;
283:   const match = updatedTournament.matches.find((m) => m.id === matchId);
284:   if (!match) return { updatedTournament, updatedPlayers: players };
285: 
286:   match.isCompleted = true;
287:   match.winnerId = winnerId;
288: 
289:   // Propagate to next match
290:   if (match.nextMatchId) {
291:     const nextMatch = updatedTournament.matches.find((m) => m.id === match.nextMatchId);
292:     if (nextMatch) {
293:       if (match.nextMatchSlot === 1) {
294:         nextMatch.player1Id = winnerId;
295:         const winnerObj = players.find((p) => p.id === winnerId);
296:         if (winnerObj && winnerObj.rank <= 32) nextMatch.seed1 = winnerObj.rank;
297:       } else {
298:         nextMatch.player2Id = winnerId;
299:         const winnerObj = players.find((p) => p.id === winnerId);
300:         if (winnerObj && winnerObj.rank <= 32) nextMatch.seed2 = winnerObj.rank;
301:       }
302:     }
303:   }
304: 
305:   // Check if final match
306:   const maxRound = Math.log2(updatedTournament.drawSize) - 1;
307:   if (match.round === maxRound) {
308:     updatedTournament.isCompleted = true;
309:     updatedTournament.championId = winnerId;
310:     const loserId = match.player1Id === winnerId ? match.player2Id : match.player1Id;
311:     if (loserId) updatedTournament.runnerUpId = loserId;
312:   }
313: 
314:   // Update player form / match records
315:   const updatedPlayers = players.map((p) => {
316:     if (p.id === winnerId) {
317:       return {
318:         ...p,
319:         matchesWon: p.matchesWon + 1,
320:         form: Math.min(1.25, p.form + 0.01),
321:       };
322:     }
323:     const loserId = match.player1Id === winnerId ? match.player2Id : match.player1Id;
324:     if (p.id === loserId) {
325:       return {
326:         ...p,
327:         matchesLost: p.matchesLost + 1,
328:         form: Math.max(0.75, p.form - 0.015),
329:       };
330:     }
331:     return p;
332:   });
333: 
334:   return { updatedTournament, updatedPlayers };
335: }
