337: export function finalizeTournamentAndDistributePoints(
338:   tournament: Tournament,
339:   players: Player[]
340: ): Player[] {
341:   const pointsMap = new Map<string, { points: number; prize: number; wonTitle: boolean }>();
342: 
343:   tournament.matches.forEach((m) => {
344:     if (m.isCompleted && m.player1Id && m.player2Id) {
345:       const loserId = m.winnerId === m.player1Id ? m.player2Id : m.player1Id;
346:       const isWinner = m.winnerId;
347: 
348:       let roundPoints = 0;
349:       let roundPrize = 0;
350: 
351:       if (m.roundName === 'Финал') {
352:         if (isWinner) {
353:           pointsMap.set(isWinner, {
354:             points: tournament.pointsWinner,
355:             prize: Math.round(tournament.prizeMoneyPool * 0.22),
356:             wonTitle: true,
357:           });
358:         }
359:         if (loserId) {
360:           pointsMap.set(loserId, {
361:             points: tournament.pointsFinalist,
362:             prize: Math.round(tournament.prizeMoneyPool * 0.12),
363:             wonTitle: false,
364:           });
365:         }
366:       } else if (m.roundName === '1/2 финала' && loserId && !pointsMap.has(loserId)) {
367:         roundPoints = tournament.pointsSemi;
368:         roundPrize = Math.round(tournament.prizeMoneyPool * 0.06);
369:         pointsMap.set(loserId, { points: roundPoints, prize: roundPrize, wonTitle: false });
370:       } else if (m.roundName === '1/4 финала' && loserId && !pointsMap.has(loserId)) {
371:         roundPoints = tournament.pointsQuarter;
372:         roundPrize = Math.round(tournament.prizeMoneyPool * 0.035);
373:         pointsMap.set(loserId, { points: roundPoints, prize: roundPrize, wonTitle: false });
374:       } else if (m.roundName === '1/8 финала' && loserId && !pointsMap.has(loserId)) {
375:         roundPoints = tournament.pointsR16;
376:         roundPrize = Math.round(tournament.prizeMoneyPool * 0.018);
377:         pointsMap.set(loserId, { points: roundPoints, prize: roundPrize, wonTitle: false });
378:       } else if (m.roundName === '1/16 финала' && loserId && !pointsMap.has(loserId)) {
379:         roundPoints = tournament.pointsR32;
380:         roundPrize = Math.round(tournament.prizeMoneyPool * 0.009);
381:         pointsMap.set(loserId, { points: roundPoints, prize: roundPrize, wonTitle: false });
382:       } else if (m.roundName === '1/32 финала' && loserId && !pointsMap.has(loserId)) {
383:         roundPoints = tournament.pointsR64;
384:         roundPrize = Math.round(tournament.prizeMoneyPool * 0.004);
385:         pointsMap.set(loserId, { points: roundPoints, prize: roundPrize, wonTitle: false });
386:       }
387:     }
388:   });
389: 
390:   const updatedPlayers = players.map((p) => {
391:     if (p.tour !== tournament.tour) return p;
392: 
393:     const tourneyPointsHistory = p.tournamentPoints || {};
394:     // Defended points = points earned at this specific tournament in the previous season edition
395:     const defendedPoints = tourneyPointsHistory[tournament.id] || 0;
396: 
397:     let earnedPoints = 0;
398:     let prize = 0;
399:     let wonTitle = false;
400: 
401:     if (pointsMap.has(p.id)) {
402:       const award = pointsMap.get(p.id)!;
403:       earnedPoints = award.points;
404:       prize = award.prize;
405:       wonTitle = award.wonTitle;
406:     } else {
407:       const playedInTournament = tournament.matches.some(
408:         (m) => m.player1Id === p.id || m.player2Id === p.id
409:       );
410:       if (playedInTournament) {
411:         earnedPoints = tournament.pointsR128 || tournament.pointsR64 || 0;
412:       }
413:     }
414: 
415:     const updatedTourneyPoints = {
416:       ...tourneyPointsHistory,
417:       [tournament.id]: earnedPoints,
418:     };
419: 
420:     const netPointsChange = earnedPoints - defendedPoints;
421:     const newPoints = Math.max(0, p.points + netPointsChange);
422: 
423:     return {
424:       ...p,
425:       previousPoints: p.points,
426:       points: newPoints,
427:       tournamentPoints: updatedTourneyPoints,
428:       prizeMoney: p.prizeMoney + prize,
429:       titles: wonTitle ? p.titles + 1 : p.titles,
430:       careerTitles: wonTitle ? p.careerTitles + 1 : p.careerTitles,
431:       grandSlams: wonTitle && tournament.category === 'Grand Slam' ? p.grandSlams + 1 : p.grandSlams,
432:     };
433:   });
434: 
435:   return recalculateRankings(updatedPlayers);
436: }
