438: export function recalculateRankings(players: Player[]): Player[] {
439:   const atp = players.filter((p) => p.tour === 'ATP' && !p.retired);
440:   const wta = players.filter((p) => p.tour === 'WTA' && !p.retired);
441:   const retired = players.filter((p) => p.retired);
442: 
443:   const sortTour = (list: Player[]) => {
444:     list.sort((a, b) => b.points - a.points || a.rank - b.rank);
445:     return list.map((p, idx) => ({
446:       ...p,
447:       previousRank: p.rank,
448:       rank: idx + 1,
449:     }));
450:   };
451: 
452:   const rankedAtp = sortTour(atp);
453:   const rankedWta = sortTour(wta);
454: 
455:   return [...rankedAtp, ...rankedWta, ...retired];
456: }
