458: export function simulateEntireTournament(
459:   tournament: Tournament,
460:   players: Player[]
461: ): { completedTournament: Tournament; updatedPlayers: Player[] } {
462:   let currTournament = JSON.parse(JSON.stringify(tournament)) as Tournament;
463:   let currPlayers = [...players];
464: 
465:   const totalRounds = Math.log2(currTournament.drawSize);
466: 
467:   for (let r = 0; r < totalRounds; r++) {
468:     const roundMatches = currTournament.matches.filter((m) => m.round === r && !m.isCompleted);
469:     for (const match of roundMatches) {
470:       if (match.player1Id && match.player2Id) {
471:         const p1 = currPlayers.find((p) => p.id === match.player1Id);
472:         const p2 = currPlayers.find((p) => p.id === match.player2Id);
473: 
474:         if (p1 && p2) {
475:           const sim = simulateFullMatch(p1, p2, currTournament.surface, currTournament.setsToWin);
476:           match.score = sim.score;
477:           const adv = advanceTournamentMatch(currTournament, match.id, sim.winnerId, currPlayers);
478:           currTournament = adv.updatedTournament;
479:           currPlayers = adv.updatedPlayers;
480:         }
481:       }
482:     }
483:   }
484: 
485:   currPlayers = finalizeTournamentAndDistributePoints(currTournament, currPlayers);
486:   return { completedTournament: currTournament, updatedPlayers: currPlayers };
487: }

