27: export function getStandardBracketSeeding(drawSize: number): number[] {
28:   const rounds = getBracketRoundCount(drawSize);
29:   let list = [1, 2];
30:   for (let r = 1; r < rounds; r++) {
31:     const nextList: number[] = [];
32:     const sum = Math.pow(2, r + 1) + 1;
33:     for (let i = 0; i < list.length; i++) {
34:       if (i % 2 === 0) {
35:         nextList.push(list[i]);
36:         nextList.push(sum - list[i]);
37:       } else {
38:         nextList.push(sum - list[i]);
39:         nextList.push(list[i]);
40:       }
41:     }
42:     list = nextList;
43:   }
44:   // The unfilled seed positions in a non-power-of-two draw become byes.
45:   return list.map((seed) => seed - 1);
