70:         const p1 = seededDraw[index * 2];
71:         const p2 = seededDraw[index * 2 + 1];
72:         match.player1Id = p1?.id || null;
73:         match.player2Id = p2?.id || null;
74:         if (p1 && p1.rank <= 32) match.seed1 = p1.rank;
75:         if (p2 && p2.rank <= 32) match.seed2 = p2.rank;
76:       }
77:       return match;
78:     });
79:     rounds.push(matches);
