82:   for (let round = 0; round < totalRounds - 1; round++) {
83:     rounds[round].forEach((match, index) => {
84:       match.nextMatchId = rounds[round + 1][Math.floor(index / 2)].id;
85:       match.nextMatchSlot = index % 2 === 0 ? 1 : 2;
86:     });
87:   }
