385: export function finalizeTournamentAndDistributePoints(
386:   tournament: Tournament,
387:   players: Player[]
388: ): Player[] {
389:   const pointsMap = new Map<string, { points: number; prize: number; wonTitle: boolean }>();
390: 
391:   tournament.matches.forEach((m) => {
392:     if (m.isCompleted && m.player1Id && m.player2Id) {
393:       const loserId = m.winnerId === m.player1Id ? m.player2Id : m.player1Id;
394:       const isWinner = m.winnerId;
395: 
396:       let roundPoints = 0;
397:       let roundPrize = 0;
398: 
399:       if (m.roundName === 'Финал') {
400:         if (isWinner) {
401:           pointsMap.set(isWinner, {
402:             points: tournament.pointsWinner,
403:             prize: Math.round(tournament.prizeMoneyPool * 0.22),
404:             wonTitle: true,
405:           });
406:         }
407:         if (loserId) {
408:           pointsMap.set(loserId, {
409:             points: tournament.pointsFinalist,
410:             prize: Math.round(tournament.prizeMoneyPool * 0.12),
411:             wonTitle: false,
412:           });
413:         }
414:       } else if (m.roundName === '1/2 финала' && loserId && !pointsMap.has(loserId)) {
415:         roundPoints = tournament.pointsSemi;
416:         roundPrize = Math.round(tournament.prizeMoneyPool * 0.06);
417:         pointsMap.set(loserId, { points: roundPoints, prize: roundPrize, wonTitle: false });
418:       } else if (m.roundName === '1/4 финала' && loserId && !pointsMap.has(loserId)) {
419:         roundPoints = tournament.pointsQuarter;
420:         roundPrize = Math.round(tournament.prizeMoneyPool * 0.035);
421:         pointsMap.set(loserId, { points: roundPoints, prize: roundPrize, wonTitle: false });
422:       } else if (m.roundName === '1/8 финала' && loserId && !pointsMap.has(loserId)) {
423:         roundPoints = tournament.pointsR16;
424:         roundPrize = Math.round(tournament.prizeMoneyPool * 0.018);
425:         pointsMap.set(loserId, { points: roundPoints, prize: roundPrize, wonTitle: false });
426:       } else if (m.roundName === '1/16 финала' && loserId && !pointsMap.has(loserId)) {
427:         roundPoints = tournament.pointsR32;
428:         roundPrize = Math.round(tournament.prizeMoneyPool * 0.009);
429:         pointsMap.set(loserId, { points: roundPoints, prize: roundPrize, wonTitle: false });
430:       } else if (m.roundName === '1/32 финала' && loserId && !pointsMap.has(loserId)) {
431:         roundPoints = tournament.pointsR64;
432:         roundPrize = Math.round(tournament.prizeMoneyPool * 0.004);
433:         pointsMap.set(loserId, { points: roundPoints, prize: roundPrize, wonTitle: false });
434:       }
435:     }
436:   });
437: 
438:   const updatedPlayers = players.map((p) => {
439:     if (p.tour !== tournament.tour) return p;
440: 
441:     const tourneyPointsHistory = p.tournamentPoints || {};
442:     // Defended points = points earned at this specific tournament in the previous season edition
443:     const defendedPoints = tourneyPointsHistory[tournament.id] || 0;
444: 
445:     let earnedPoints = 0;
446:     let prize = 0;
447:     let wonTitle = false;
448: 
449:     if (pointsMap.has(p.id)) {
450:       const award = pointsMap.get(p.id)!;
451:       earnedPoints = award.points;
452:       prize = award.prize;
453:       wonTitle = award.wonTitle;
454:     } else {
455:       const playedInTournament = tournament.matches.some(
456:         (m) => m.player1Id === p.id || m.player2Id === p.id
457:       );
458:       if (playedInTournament) {
459:         earnedPoints = tournament.pointsR128 || tournament.pointsR64 || 0;
460:       }
461:     }
462: 
463:     const updatedTourneyPoints = {
464:       ...tourneyPointsHistory,
465:       [tournament.id]: earnedPoints,
466:     };
467: 
468:     const netPointsChange = earnedPoints - defendedPoints;
469:     const newPoints = Math.max(0, p.points + netPointsChange);
470: 
471:     return {
472:       ...p,
473:       previousPoints: p.points,
474:       points: newPoints,
475:       tournamentPoints: updatedTourneyPoints,
476:       prizeMoney: p.prizeMoney + prize,
477:       titles: wonTitle ? p.titles + 1 : p.titles,
478:       careerTitles: wonTitle ? p.careerTitles + 1 : p.careerTitles,
479:       grandSlams: wonTitle && tournament.category === 'Grand Slam' ? p.grandSlams + 1 : p.grandSlams,
480:     };
481:   });
482: 
483:   return recalculateRankings(updatedPlayers);
484: }
