322: export function advanceTournamentMatch(
323:   tournament: Tournament,
324:   matchId: string,
325:   winnerId: string,
326:   players: Player[]
327: ): { updatedTournament: Tournament; updatedPlayers: Player[] } {
328:   const updatedTournament = JSON.parse(JSON.stringify(tournament)) as Tournament;
329:   const match = updatedTournament.matches.find((m) => m.id === matchId);
330:   if (
331:     !match || match.isCompleted ||
332:     (match.player1Id !== winnerId && match.player2Id !== winnerId) ||
333:     !match.player1Id || !match.player2Id
334:   ) {
335:     return { updatedTournament, updatedPlayers: players };
336:   }
337: 
338:   match.isCompleted = true;
339:   match.winnerId = winnerId;
340: 
341:   // Propagate to next match
342:   if (match.nextMatchId) {
343:     const nextMatch = updatedTournament.matches.find((m) => m.id === match.nextMatchId);
344:     if (nextMatch) {
345:       if (match.nextMatchSlot === 1) {
346:         nextMatch.player1Id = winnerId;
347:         const winnerObj = players.find((p) => p.id === winnerId);
348:         if (winnerObj && winnerObj.rank <= 32) nextMatch.seed1 = winnerObj.rank;
349:       } else {
350:         nextMatch.player2Id = winnerId;
351:         const winnerObj = players.find((p) => p.id === winnerId);
352:         if (winnerObj && winnerObj.rank <= 32) nextMatch.seed2 = winnerObj.rank;
353:       }
354:     }
355:   }
356: 
357:   resolveBracketByes(updatedTournament);
358:   const totalRounds = getBracketRoundCount(updatedTournament.drawSize);
359:   const nextUnplayedRound = updatedTournament.matches.find((candidate) => !candidate.isCompleted)?.round;
360:   updatedTournament.currentRound = nextUnplayedRound ?? totalRounds;
361: 
362:   // Update player form / match records
363:   const updatedPlayers = players.map((p) => {
364:     if (p.id === winnerId) {
365:       return {
366:         ...p,
367:         matchesWon: p.matchesWon + 1,
368:         form: Math.min(1.25, p.form + 0.01),
369:       };
370:     }
371:     const loserId = match.player1Id === winnerId ? match.player2Id : match.player1Id;
372:     if (p.id === loserId) {
373:       return {
374:         ...p,
375:         matchesLost: p.matchesLost + 1,
376:         form: Math.max(0.75, p.form - 0.015),
377:       };
378:     }
379:     return p;
380:   });
381: 
382:   return { updatedTournament, updatedPlayers };
383: }
