527:           currPlayers = adv.updatedPlayers;
528:         }
529:       }
530:     }
531:   }
532: 
533:   currPlayers = finalizeTournamentAndDistributePoints(currTournament, currPlayers);
534:   return { completedTournament: currTournament, updatedPlayers: currPlayers };
535: }

