155: export function repairTournamentBracket(tournament: Tournament, allPlayers: Player[]): Tournament {
156:   const totalRounds = getBracketRoundCount(tournament.drawSize);
157:   const bracketSize = getBracketSize(tournament.drawSize);
158:   const hasValidShape = Array.from({ length: totalRounds }, (_, round) => {
159:     const expectedCount = bracketSize / (2 ** (round + 1));
160:     return tournament.matches.filter((match) => match.round === round).length === expectedCount;
161:   }).every(Boolean);
162: 
163:   if (!hasValidShape) {
164:     const eligiblePlayers = allPlayers
165:       .filter((player) => player.tour === tournament.tour && !player.retired)
166:       .sort((a, b) => a.rank - b.rank);
167:     const fresh = generateTournamentDraw(tournament, allPlayers);
168:     const oldFirstRound = tournament.matches
169:       .filter((match) => match.round === 0)
170:       .sort((a, b) => Number(a.id.split('-m').pop()) - Number(b.id.split('-m').pop()));
171:     const newFirstRound = fresh.matches.filter((match) => match.round === 0);
172:     const eligibleIds = new Set(eligiblePlayers.map((player) => player.id));
173:     const assigned = new Set<string>();
174:     const oldResults = new Map<string, Match>();
175: 
176:     // Preserve the old draw order where possible, without leaving generated duplicates behind.
177:     newFirstRound.forEach((match) => {
178:       match.player1Id = null;
179:       match.player2Id = null;
180:       match.seed1 = undefined;
181:       match.seed2 = undefined;
182:     });
183:     for (const oldMatch of oldFirstRound) {
184:       const newMatch = newFirstRound.find((match) => match.id === oldMatch.id);
185:       if (!newMatch) continue;
186:       for (const [slot, playerId] of [[1, oldMatch.player1Id], [2, oldMatch.player2Id]] as const) {
187:         if (!playerId || assigned.has(playerId) || !eligibleIds.has(playerId)) continue;
188:         if (slot === 1) {
189:           newMatch.player1Id = playerId;
190:           newMatch.seed1 = oldMatch.seed1 || allPlayers.find((player) => player.id === playerId)?.rank;
191:         } else {
192:           newMatch.player2Id = playerId;
193:           newMatch.seed2 = oldMatch.seed2 || allPlayers.find((player) => player.id === playerId)?.rank;
194:         }
195:         assigned.add(playerId);
196:       }
197:       if (oldMatch.isCompleted && oldMatch.winnerId && oldMatch.player1Id && oldMatch.player2Id) {
198:         oldResults.set(oldMatch.id, oldMatch);
199:       }
200:     }
201: 
202:     // Retain original seeding for newly added entrants, while ensuring each player appears once.
203:     const generatedFirstRound = generateTournamentDraw(tournament, allPlayers).matches.filter((match) => match.round === 0);
204:     generatedFirstRound.forEach((generatedMatch) => {
205:       const target = newFirstRound.find((match) => match.id === generatedMatch.id);
206:       if (!target) return;
207:       for (const [slot, playerId] of [[1, generatedMatch.player1Id], [2, generatedMatch.player2Id]] as const) {
208:         if (!playerId || assigned.has(playerId)) continue;
209:         if (slot === 1 && !target.player1Id) {
210:           target.player1Id = playerId;
211:           target.seed1 = generatedMatch.seed1;
212:           assigned.add(playerId);
213:         } else if (slot === 2 && !target.player2Id) {
214:           target.player2Id = playerId;
215:           target.seed2 = generatedMatch.seed2;
216:           assigned.add(playerId);
217:         }
218:       }
219:     });
220:     const missingPlayers = eligiblePlayers.filter((player) => !assigned.has(player.id));
221:     let nextPlayer = 0;
222:     newFirstRound.forEach((match) => {
223:       if (!match.player1Id && nextPlayer < missingPlayers.length) match.player1Id = missingPlayers[nextPlayer++].id;
224:       if (!match.player2Id && nextPlayer < missingPlayers.length) match.player2Id = missingPlayers[nextPlayer++].id;
225:     });
226:     newFirstRound.forEach((match) => {
227:       match.seed1 = match.player1Id ? (match.seed1 || allPlayers.find((player) => player.id === match.player1Id)?.rank) : undefined;
228:       match.seed2 = match.player2Id ? (match.seed2 || allPlayers.find((player) => player.id === match.player2Id)?.rank) : undefined;
229:       const oldMatch = oldResults.get(match.id);
230:       if (oldMatch && oldMatch.winnerId && [match.player1Id, match.player2Id].includes(oldMatch.winnerId)) {
231:         match.isCompleted = true;
232:         match.winnerId = oldMatch.winnerId;
233:         match.score = oldMatch.score;
234:       }
235:     });
236: 
237:     // Only keep later results if the repaired bracket still gives the match the same players.
238:     resolveBracketByes(fresh);
239:     for (let round = 1; round < totalRounds; round++) {
240:       for (const rebuiltMatch of fresh.matches.filter((match) => match.round === round)) {
241:         const oldMatch = tournament.matches.find((match) => match.id === rebuiltMatch.id);
242:         if (
243:           oldMatch?.isCompleted && oldMatch.winnerId &&
244:           oldMatch.player1Id === rebuiltMatch.player1Id && oldMatch.player2Id === rebuiltMatch.player2Id &&
245:           rebuiltMatch.player1Id && rebuiltMatch.player2Id
246:         ) {
247:           rebuiltMatch.isCompleted = true;
248:           rebuiltMatch.winnerId = oldMatch.winnerId;
249:           rebuiltMatch.score = oldMatch.score;
250:         }
251:       }
252:       resolveBracketByes(fresh);
253:     }
254:     fresh.currentRound = fresh.matches.find((match) => !match.isCompleted)?.round ?? totalRounds;
255:     return fresh;
256:   }
257: 
258:   const updatedTournament = JSON.parse(JSON.stringify(tournament)) as Tournament;
259:   const eligiblePlayers = allPlayers
260:     .filter((player) => player.tour === updatedTournament.tour && !player.retired)
261:     .sort((a, b) => a.rank - b.rank);
262:   const firstRound = updatedTournament.matches.filter((match) => match.round === 0);
263:   const assignedPlayerIds = new Set(firstRound.flatMap((match) => [match.player1Id, match.player2Id].filter(Boolean) as string[]));
264:   const unassignedPlayers = eligiblePlayers.filter((player) => !assignedPlayerIds.has(player.id));
265:   let nextPlayer = 0;
266: 
267:   firstRound.forEach((match) => {
268:     if (!match.player1Id && nextPlayer < unassignedPlayers.length) match.player1Id = unassignedPlayers[nextPlayer++].id;
269:     if (!match.player2Id && nextPlayer < unassignedPlayers.length) match.player2Id = unassignedPlayers[nextPlayer++].id;
270:   });
271: 
272:   for (let round = 0; round < totalRounds - 1; round++) {
273:     const currentMatches = updatedTournament.matches.filter((match) => match.round === round);
274:     const nextMatches = updatedTournament.matches.filter((match) => match.round === round + 1);
275:     currentMatches.forEach((match, index) => {
276:       match.roundName = getRoundName(round, totalRounds);
277:       match.nextMatchId = nextMatches[Math.floor(index / 2)].id;
278:       match.nextMatchSlot = index % 2 === 0 ? 1 : 2;
279:     });
280:   }
281:   updatedTournament.matches
282:     .filter((match) => match.round === totalRounds - 1)
283:     .forEach((match) => {
284:       match.roundName = getRoundName(match.round, totalRounds);
285:       match.nextMatchId = undefined;
286:       match.nextMatchSlot = undefined;
287:     });
288:   resolveBracketByes(updatedTournament);
289:   updatedTournament.currentRound = updatedTournament.matches.find((match) => !match.isCompleted)?.round ?? totalRounds;
290:   return updatedTournament;
291: }
