506: export function simulateEntireTournament(
507:   tournament: Tournament,
508:   players: Player[]
509: ): { completedTournament: Tournament; updatedPlayers: Player[] } {
510:   let currTournament = JSON.parse(JSON.stringify(tournament)) as Tournament;
511:   let currPlayers = [...players];
512: 
513:   const totalRounds = getBracketRoundCount(currTournament.drawSize);
514: 
515:   for (let r = 0; r < totalRounds; r++) {
516:     const roundMatches = currTournament.matches.filter((m) => m.round === r && !m.isCompleted);
517:     for (const match of roundMatches) {
518:       if (match.player1Id && match.player2Id) {
519:         const p1 = currPlayers.find((p) => p.id === match.player1Id);
520:         const p2 = currPlayers.find((p) => p.id === match.player2Id);
521: 
522:         if (p1 && p2) {
523:           const sim = simulateFullMatch(p1, p2, currTournament.surface, currTournament.setsToWin);
524:           match.score = sim.score;
525:           const adv = advanceTournamentMatch(currTournament, match.id, sim.winnerId, currPlayers);
526:           currTournament = adv.updatedTournament;
527:           currPlayers = adv.updatedPlayers;
528:         }
529:       }
530:     }
531:   }
532: 
533:   currPlayers = finalizeTournamentAndDistributePoints(currTournament, currPlayers);
534:   return { completedTournament: currTournament, updatedPlayers: currPlayers };
535: }

