91: function resolveBracketByes(tournament: Tournament): void {
92:   const totalRounds = getBracketRoundCount(tournament.drawSize);
93:   for (let round = 0; round < totalRounds; round++) {
94:     const matches = tournament.matches.filter((match) => match.round === round);
95:     for (const match of matches) {
96:       if (round > 0) {
97:         const previousRound = tournament.matches.filter((candidate) => candidate.round === round - 1);
98:         const childMatches = previousRound.filter((child) => child.nextMatchId === match.id);
99:         if (childMatches.length !== 2 || childMatches.some((child) => !child.isCompleted)) continue;
100:         const [first, second] = childMatches.sort((a, b) => (a.nextMatchSlot || 0) - (b.nextMatchSlot || 0));
101:         match.player1Id = first.winnerId || null;
102:         match.player2Id = second.winnerId || null;
103:         match.seed1 = first.winnerId === first.player1Id ? first.seed1 : first.winnerId === first.player2Id ? first.seed2 : undefined;
104:         match.seed2 = second.winnerId === second.player1Id ? second.seed1 : second.winnerId === second.player2Id ? second.seed2 : undefined;
105:       }
106: 
107:       if (!match.player1Id || !match.player2Id) {
108:         match.isCompleted = true;
109:         match.winnerId = match.player1Id || match.player2Id || undefined;
110:         match.score = undefined;
111:       } else if (match.isCompleted && !match.score) {
112:         // A former bye is now a real match after a bracket repair or player fill-in.
113:         match.isCompleted = false;
114:         match.winnerId = undefined;
115:       }
116:     }
117:   }
118: 
119:   const finalRound = totalRounds - 1;
120:   const finalMatch = tournament.matches.find((match) => match.round === finalRound);
121:   if (finalMatch?.isCompleted && finalMatch.winnerId) {
122:     tournament.isCompleted = true;
123:     tournament.championId = finalMatch.winnerId;
124:     const loserId = finalMatch.player1Id === finalMatch.winnerId ? finalMatch.player2Id : finalMatch.player1Id;
125:     tournament.runnerUpId = loserId || undefined;
126:   }
127: }
