155: export function repairTournamentBracket(tournament: Tournament, allPlayers: Player[]): Tournament {
156:   const totalRounds = getBracketRoundCount(tournament.drawSize);
157:   const bracketSize = getBracketSize(tournament.drawSize);
158:   const hasValidShape = Array.from({ length: totalRounds }, (_, round) => {
159:     const expectedCount = bracketSize / (2 ** (round + 1));
160:     return tournament.matches.filter((match) => match.round === round).length === expectedCount;
161:   }).every(Boolean);
162: 
163:   if (!hasValidShape) {
164:     const eligiblePlayers = allPlayers
165:       .filter((player) => player.tour === tournament.tour && !player.retired)
