486: export function recalculateRankings(players: Player[]): Player[] {
487:   const atp = players.filter((p) => p.tour === 'ATP' && !p.retired);
488:   const wta = players.filter((p) => p.tour === 'WTA' && !p.retired);
489:   const retired = players.filter((p) => p.retired);
490: 
491:   const sortTour = (list: Player[]) => {
492:     list.sort((a, b) => b.points - a.points || a.rank - b.rank);
493:     return list.map((p, idx) => ({
494:       ...p,
495:       previousRank: p.rank,
496:       rank: idx + 1,
497:     }));
498:   };
499: 
500:   const rankedAtp = sortTour(atp);
501:   const rankedWta = sortTour(wta);
502: 
503:   return [...rankedAtp, ...rankedWta, ...retired];
504: }
