export function repairTournamentBracket(tournament: Tournament, allPlayers: Player[]): Tournament {
  const totalRounds = getBracketRoundCount(tournament.drawSize);
  const bracketSize = getBracketSize(tournament.drawSize);
  const hasValidShape = Array.from({ length: totalRounds }, (_, round) => {
    const expectedCount = bracketSize / (2 ** (round + 1));
    return tournament.matches.filter((match) => match.round === round).length === expectedCount;
  }).every(Boolean);

  if (!hasValidShape) {
    const eligiblePlayers = allPlayers
      .filter((player) => player.tour === tournament.tour && !player.retired)
      .sort((a, b) => a.rank - b.rank);
    const fresh = generateTournamentDraw(tournament, allPlayers);
    const oldFirstRound = tournament.matches
      .filter((match) => match.round === 0)
      .sort((a, b) => Number(a.id.split('-m').pop()) - Number(b.id.split('-m').pop()));
    const newFirstRound = fresh.matches.filter((match) => match.round === 0);
    const eligibleIds = new Set(eligiblePlayers.map((player) => player.id));
    const assigned = new Set<string>();
    const oldResults = new Map<string, Match>();

    // Preserve the old draw order where possible, without leaving generated duplicates behind.
    newFirstRound.forEach((match) => {
      match.player1Id = null;
      match.player2Id = null;
      match.seed1 = undefined;
      match.seed2 = undefined;
    });
    for (const oldMatch of oldFirstRound) {
      const newMatch = newFirstRound.find((match) => match.id === oldMatch.id);
      if (!newMatch) continue;
      for (const [slot, playerId] of [[1, oldMatch.player1Id], [2, oldMatch.player2Id]] as const) {
        if (!playerId || assigned.has(playerId) || !eligibleIds.has(playerId)) continue;
        if (slot === 1) {
          newMatch.player1Id = playerId;
          newMatch.seed1 = oldMatch.seed1 || allPlayers.find((player) => player.id === playerId)?.rank;
        } else {
          newMatch.player2Id = playerId;
          newMatch.seed2 = oldMatch.seed2 || allPlayers.find((player) => player.id === playerId)?.rank;
        }
        assigned.add(playerId);
      }
      if (oldMatch.isCompleted && oldMatch.winnerId && oldMatch.player1Id && oldMatch.player2Id) {
        oldResults.set(oldMatch.id, oldMatch);
      }
    }

    // Retain original seeding for newly added entrants, while ensuring each player appears once.
    const generatedFirstRound = generateTournamentDraw(tournament, allPlayers).matches.filter((match) => match.round === 0);
    generatedFirstRound.forEach((generatedMatch) => {
      const target = newFirstRound.find((match) => match.id === generatedMatch.id);
      if (!target) return;
      for (const [slot, playerId] of [[1, generatedMatch.player1Id], [2, generatedMatch.player2Id]] as const) {
        if (!playerId || assigned.has(playerId)) continue;
        if (slot === 1 && !target.player1Id) {
          target.player1Id = playerId;
          target.seed1 = generatedMatch.seed1;
          assigned.add(playerId);
        } else if (slot === 2 && !target.player2Id) {
          target.player2Id = playerId;
          target.seed2 = generatedMatch.seed2;
          assigned.add(playerId);
        }
      }
    });
    const missingPlayers = eligiblePlayers.filter((player) => !assigned.has(player.id));
    let nextPlayer = 0;
    newFirstRound.forEach((match) => {
      if (!match.player1Id && nextPlayer < missingPlayers.length) match.player1Id = missingPlayers[nextPlayer++].id;
      if (!match.player2Id && nextPlayer < missingPlayers.length) match.player2Id = missingPlayers[nextPlayer++].id;
    });
    newFirstRound.forEach((match) => {
      match.seed1 = match.player1Id ? (match.seed1 || allPlayers.find((player) => player.id === match.player1Id)?.rank) : undefined;
      match.seed2 = match.player2Id ? (match.seed2 || allPlayers.find((player) => player.id === match.player2Id)?.rank) : undefined;
      const oldMatch = oldResults.get(match.id);
      if (oldMatch && oldMatch.winnerId && [match.player1Id, match.player2Id].includes(oldMatch.winnerId)) {
        match.isCompleted = true;
        match.winnerId = oldMatch.winnerId;
        match.score = oldMatch.score;
      }
    });

    // Only keep later results if the repaired bracket still gives the match the same players.
    resolveBracketByes(fresh);
    for (let round = 1; round < totalRounds; round++) {
      for (const rebuiltMatch of fresh.matches.filter((match) => match.round === round)) {
        const oldMatch = tournament.matches.find((match) => match.id === rebuiltMatch.id);
        if (
          oldMatch?.isCompleted && oldMatch.winnerId &&
          oldMatch.player1Id === rebuiltMatch.player1Id && oldMatch.player2Id === rebuiltMatch.player2Id &&
          rebuiltMatch.player1Id && rebuiltMatch.player2Id
        ) {
          rebuiltMatch.isCompleted = true;
          rebuiltMatch.winnerId = oldMatch.winnerId;
          rebuiltMatch.score = oldMatch.score;
        }
      }
      resolveBracketByes(fresh);
    }
    fresh.currentRound = fresh.matches.find((match) => !match.isCompleted)?.round ?? totalRounds;
    return fresh;
