377: export function finalizeTournamentAndDistributePoints(
378:   tournament: Tournament,
379:   players: Player[]
380: ): Player[] {
381:   const pointsMap = new Map<string, { points: number; prize: number; wonTitle: boolean }>();
382: 
383:   tournament.matches.forEach((m) => {
384:     if (m.isCompleted && m.player1Id && m.player2Id) {
385:       const loserId = m.winnerId === m.player1Id ? m.player2Id : m.player1Id;
386:       const isWinner = m.winnerId;
387: 
388:       let roundPoints = 0;
389:       let roundPrize = 0;
390: 
391:       if (m.roundName === 'Финал') {
392:         if (isWinner) {
393:           pointsMap.set(isWinner, {
394:             points: tournament.pointsWinner,
395:             prize: Math.round(tournament.prizeMoneyPool * 0.22),
396:             wonTitle: true,
397:           });
398:         }
399:         if (loserId) {
400:           pointsMap.set(loserId, {
401:             points: tournament.pointsFinalist,
402:             prize: Math.round(tournament.prizeMoneyPool * 0.12),
403:             wonTitle: false,
404:           });
405:         }
406:       } else if (m.roundName === '1/2 финала' && loserId && !pointsMap.has(loserId)) {
407:         roundPoints = tournament.pointsSemi;
408:         roundPrize = Math.round(tournament.prizeMoneyPool * 0.06);
409:         pointsMap.set(loserId, { points: roundPoints, prize: roundPrize, wonTitle: false });
410:       } else if (m.roundName === '1/4 финала' && loserId && !pointsMap.has(loserId)) {
411:         roundPoints = tournament.pointsQuarter;
412:         roundPrize = Math.round(tournament.prizeMoneyPool * 0.035);
413:         pointsMap.set(loserId, { points: roundPoints, prize: roundPrize, wonTitle: false });
414:       } else if (m.roundName === '1/8 финала' && loserId && !pointsMap.has(loserId)) {
415:         roundPoints = tournament.pointsR16;
416:         roundPrize = Math.round(tournament.prizeMoneyPool * 0.018);
417:         pointsMap.set(loserId, { points: roundPoints, prize: roundPrize, wonTitle: false });
418:       } else if (m.roundName === '1/16 финала' && loserId && !pointsMap.has(loserId)) {
419:         roundPoints = tournament.pointsR32;
420:         roundPrize = Math.round(tournament.prizeMoneyPool * 0.009);
421:         pointsMap.set(loserId, { points: roundPoints, prize: roundPrize, wonTitle: false });
422:       } else if (m.roundName === '1/32 финала' && loserId && !pointsMap.has(loserId)) {
423:         roundPoints = tournament.pointsR64;
424:         roundPrize = Math.round(tournament.prizeMoneyPool * 0.004);
425:         pointsMap.set(loserId, { points: roundPoints, prize: roundPrize, wonTitle: false });
426:       }
427:     }
428:   });
429: 
430:   const updatedPlayers = players.map((p) => {
431:     if (p.tour !== tournament.tour) return p;
432: 
433:     const tourneyPointsHistory = p.tournamentPoints || {};
434:     // Defended points = points earned at this specific tournament in the previous season edition
435:     const defendedPoints = tourneyPointsHistory[tournament.id] || 0;
436: 
437:     let earnedPoints = 0;
438:     let prize = 0;
439:     let wonTitle = false;
440: 
441:     if (pointsMap.has(p.id)) {
442:       const award = pointsMap.get(p.id)!;
443:       earnedPoints = award.points;
444:       prize = award.prize;
445:       wonTitle = award.wonTitle;
446:     } else {
447:       const playedInTournament = tournament.matches.some(
448:         (m) => m.player1Id === p.id || m.player2Id === p.id
449:       );
450:       if (playedInTournament) {
451:         earnedPoints = tournament.pointsR128 || tournament.pointsR64 || 0;
452:       }
453:     }
454: 
455:     const updatedTourneyPoints = {
456:       ...tourneyPointsHistory,
457:       [tournament.id]: earnedPoints,
458:     };
459: 
460:     const netPointsChange = earnedPoints - defendedPoints;
461:     const newPoints = Math.max(0, p.points + netPointsChange);
462: 
463:     return {
464:       ...p,
465:       previousPoints: p.points,
466:       points: newPoints,
467:       tournamentPoints: updatedTourneyPoints,
468:       prizeMoney: p.prizeMoney + prize,
469:       titles: wonTitle ? p.titles + 1 : p.titles,
470:       careerTitles: wonTitle ? p.careerTitles + 1 : p.careerTitles,
471:       grandSlams: wonTitle && tournament.category === 'Grand Slam' ? p.grandSlams + 1 : p.grandSlams,
472:     };
473:   });
474: 
475:   return recalculateRankings(updatedPlayers);
476: }
