478: export function recalculateRankings(players: Player[]): Player[] {
479:   const atp = players.filter((p) => p.tour === 'ATP' && !p.retired);
480:   const wta = players.filter((p) => p.tour === 'WTA' && !p.retired);
481:   const retired = players.filter((p) => p.retired);
482: 
483:   const sortTour = (list: Player[]) => {
484:     list.sort((a, b) => b.points - a.points || a.rank - b.rank);
485:     return list.map((p, idx) => ({
486:       ...p,
487:       previousRank: p.rank,
488:       rank: idx + 1,
489:     }));
490:   };
491: 
492:   const rankedAtp = sortTour(atp);
493:   const rankedWta = sortTour(wta);
494: 
495:   return [...rankedAtp, ...rankedWta, ...retired];
496: }
