498: export function simulateEntireTournament(
499:   tournament: Tournament,
500:   players: Player[]
501: ): { completedTournament: Tournament; updatedPlayers: Player[] } {
502:   let currTournament = JSON.parse(JSON.stringify(tournament)) as Tournament;
503:   let currPlayers = [...players];
504: 
505:   const totalRounds = getBracketRoundCount(currTournament.drawSize);
506: 
507:   for (let r = 0; r < totalRounds; r++) {
508:     const roundMatches = currTournament.matches.filter((m) => m.round === r && !m.isCompleted);
509:     for (const match of roundMatches) {
510:       if (match.player1Id && match.player2Id) {
511:         const p1 = currPlayers.find((p) => p.id === match.player1Id);
512:         const p2 = currPlayers.find((p) => p.id === match.player2Id);
513: 
514:         if (p1 && p2) {
515:           const sim = simulateFullMatch(p1, p2, currTournament.surface, currTournament.setsToWin);
516:           match.score = sim.score;
517:           const adv = advanceTournamentMatch(currTournament, match.id, sim.winnerId, currPlayers);
518:           currTournament = adv.updatedTournament;
519:           currPlayers = adv.updatedPlayers;
520:         }
521:       }
522:     }
523:   }
524: 
525:   currPlayers = finalizeTournamentAndDistributePoints(currTournament, currPlayers);
526:   return { completedTournament: currTournament, updatedPlayers: currPlayers };
527: }

