4: import { formatGameScore, simulateSinglePoint } from '../engine/tennisEngine';
5: import { soundFx } from '../utils/audio';
6: 
7: interface MatchViewerProps {
8:   match: Match;
9:   player1: Player;
10:   player2: Player;
11:   surface: SurfaceType;
12:   setsToWin: 2 | 3;
13:   onMatchFinished: (matchId: string, winnerId: string, score: MatchScore) => void;
14:   onBackToBracket: () => void;
15: }
16: 
17: export const MatchViewer: React.FC<MatchViewerProps> = ({
18:   match,
19:   player1,
20:   player2,
21:   surface,
22:   setsToWin,
23:   onMatchFinished,
24:   onBackToBracket,
25: }) => {
26:   // Live state
27:   const [sets, setSets] = useState<Array<[number, number]>>(
28:     match.score ? match.score.sets : [[0, 0]]
29:   );
30:   const [currentSetIdx, setCurrentSetIdx] = useState<number>(
31:     match.score ? match.score.sets.length - 1 : 0
32:   );
33:   const [currentGamePoints, setCurrentGamePoints] = useState<[number, number]>([0, 0]);
34:   const [server, setServer] = useState<1 | 2>(1);
35:   const [inTiebreak, setInTiebreak] = useState<boolean>(false);
36:   const [tiebreakScore, setTiebreakScore] = useState<[number, number]>([0, 0]);
37:   const [isMatchOver, setIsMatchOver] = useState<boolean>(match.isCompleted);
38:   const [matchWinner, setMatchWinner] = useState<string | null>(match.winnerId || null);
39:   const [pointLogs, setPointLogs] = useState<string[]>([]);
40:   const [isAutoPlaying, setIsAutoPlaying] = useState<boolean>(false);
41:   const [autoPlaySpeed, setAutoPlaySpeed] = useState<number>(800); // ms per point
42:   const [isMuted, setIsMuted] = useState<boolean>(soundFx.getMuted());
43:   const [ballPos, setBallPos] = useState<{ x: number; y: number }>({ x: 50, y: 50 });
44:   const [isBallActive, setIsBallActive] = useState<boolean>(false);
45: 
46:   // Match stats
47:   const [stats, setStats] = useState<MatchDetailedStats>(
48:     match.score?.stats || {
49:       aces: [0, 0],
50:       doubleFaults: [0, 0],
51:       firstServePercentage: [65, 63],
52:       firstServePointsWon: [0, 0],
53:       secondServePointsWon: [0, 0],
54:       breakPointsConverted: [0, 0],
55:       breakPointsTotal: [0, 0],
56:       winners: [0, 0],
57:       unforcedErrors: [0, 0],
58:       totalPointsWon: [0, 0],
59:       fastestServeKmH: [
60:         Math.round(205 + (player1.stats.serve - 70) * 0.7),
61:         Math.round(205 + (player2.stats.serve - 70) * 0.7),
62:       ],
63:     }
64:   );
65: 
66:   const logsContainerRef = useRef<HTMLDivElement>(null);
67: 
68:   // Auto-scroll internal log container only (without shifting browser window)
69:   useEffect(() => {
70:     if (logsContainerRef.current) {
71:       logsContainerRef.current.scrollTop = logsContainerRef.current.scrollHeight;
72:     }
73:   }, [pointLogs]);
74: 
75:   // Point simulator step
76:   const handlePlayNextPoint = () => {
77:     if (isMatchOver) return;
78: 
79:     const currentP1Games = sets[currentSetIdx] ? sets[currentSetIdx][0] : 0;
80:     const currentP2Games = sets[currentSetIdx] ? sets[currentSetIdx][1] : 0;
81: 
82:     let p1Pt = inTiebreak ? tiebreakScore[0] : currentGamePoints[0];
83:     let p2Pt = inTiebreak ? tiebreakScore[1] : currentGamePoints[1];
84: 
85:     const ptResult = simulateSinglePoint(
86:       player1,
87:       player2,
88:       surface,
89:       server,
90:       inTiebreak,
91:       p1Pt,
92:       p2Pt
93:     );
94: 
95:     // Audio SFX
96:     if (ptResult.outcomeType === 'ace') {
97:       soundFx.playAce();
98:     } else if (ptResult.outcomeType === 'double_fault') {
99:       // no hit
100:     } else {
101:       soundFx.playRacketHit(ptResult.outcomeType === 'winner');
102:     }
103: 
104:     // Visual Ball Animation
105:     setIsBallActive(true);
106:     setBallPos(ptResult.ballPath[ptResult.ballPath.length - 1]);
107: 
108:     // Update Stats
109:     const updatedStats = { ...stats };
110:     if (ptResult.winner === 1) updatedStats.totalPointsWon[0]++;
111:     else updatedStats.totalPointsWon[1]++;
112: 
113:     if (ptResult.outcomeType === 'ace') updatedStats.aces[ptResult.winner - 1]++;
114:     if (ptResult.outcomeType === 'double_fault') updatedStats.doubleFaults[ptResult.winner === 1 ? 1 : 0]++;
115:     if (ptResult.outcomeType === 'winner') updatedStats.winners[ptResult.winner - 1]++;
116:     if (ptResult.outcomeType === 'unforced_error') updatedStats.unforcedErrors[ptResult.winner === 1 ? 1 : 0]++;
117:     setStats(updatedStats);
118: 
119:     // Add log
120:     setPointLogs((prev) => [...prev.slice(-40), ptResult.descriptionRu]);
121: 
122:     // Handle Tiebreak logic
123:     if (inTiebreak) {
124:       const newTb: [number, number] = [
125:         ptResult.winner === 1 ? p1Pt + 1 : p1Pt,
126:         ptResult.winner === 2 ? p2Pt + 1 : p2Pt,
127:       ];
128:       setTiebreakScore(newTb);
129: 
130:       // Server toggle in tiebreak (every 2 points after 1st point)
131:       if ((newTb[0] + newTb[1]) % 2 === 1) {
132:         setServer((s) => (s === 1 ? 2 : 1));
133:       }
134: 
135:       // Check Tiebreak won (7 points with 2 pt margin)
136:       if ((newTb[0] >= 7 || newTb[1] >= 7) && Math.abs(newTb[0] - newTb[1]) >= 2) {
137:         const tbWinner = newTb[0] > newTb[1] ? 1 : 2;
138:         handleSetWon(tbWinner, true, sets);
139:       }
140:       return;
141:     }
142: 
143:     // Handle Regular Game Logic
144:     let newP1Pt = ptResult.winner === 1 ? p1Pt + 1 : p1Pt;
145:     let newP2Pt = ptResult.winner === 2 ? p2Pt + 1 : p2Pt;
146: 
147:     // Game won check
148:     if (newP1Pt >= 4 && newP1Pt - newP2Pt >= 2) {
149:       handleGameWon(1);
150:     } else if (newP2Pt >= 4 && newP2Pt - newP1Pt >= 2) {
151:       handleGameWon(2);
152:     } else {
153:       setCurrentGamePoints([newP1Pt, newP2Pt]);
154:     }
155:   };
156: 
157:   const handleGameWon = (gameWinner: 1 | 2) => {
158:     soundFx.playCrowdApplause();
159:     setCurrentGamePoints([0, 0]);
160:     const updatedSets = [...sets];
161:     const currSet = [...updatedSets[currentSetIdx]] as [number, number];
162: 
163:     if (gameWinner === 1) currSet[0]++;
164:     else currSet[1]++;
165:     updatedSets[currentSetIdx] = currSet;
166:     setSets(updatedSets);
167: 
168:     // Switch server
169:     setServer((s) => (s === 1 ? 2 : 1));
170: 
171:     // Check Set Won
172:     if (currSet[0] >= 6 && currSet[0] - currSet[1] >= 2) {
173:       handleSetWon(1, false, updatedSets);
174:     } else if (currSet[1] >= 6 && currSet[1] - currSet[0] >= 2) {
175:       handleSetWon(2, false, updatedSets);
176:     } else if (currSet[0] === 6 && currSet[1] === 6) {
177:       // Enter Tiebreak!
178:       setInTiebreak(true);
179:       setTiebreakScore([0, 0]);
180:       setPointLogs((prev) => [...prev, '🔥 ТАЙ-БРЕЙК ДО 7 ОЧКОВ!']);
181:     }
182:   };
183: 
184:   const handleSetWon = (setWinner: 1 | 2, wasTiebreak: boolean, currentSets: Array<[number, number]>) => {
185:     setInTiebreak(false);
186:     setTiebreakScore([0, 0]);
187:     setCurrentGamePoints([0, 0]);
188: 
189:     let updatedSets = JSON.parse(JSON.stringify(currentSets)) as Array<[number, number]>;
190:     if (wasTiebreak) {
191:       const curr = [...updatedSets[currentSetIdx]] as [number, number];
192:       if (setWinner === 1) curr[0] = 7;
193:       else curr[1] = 7;
194:       updatedSets[currentSetIdx] = curr;
195:     }
196: 
197:     setSets(updatedSets);
198: 
199:     // Count sets won
200:     let p1Sets = 0;
201:     let p2Sets = 0;
202:     updatedSets.forEach((s) => {
203:       if (s[0] > s[1]) p1Sets++;
204:       else if (s[1] > s[0]) p2Sets++;
205:     });
206: 
207:     const setWinnerPlayer = setWinner === 1 ? player1 : player2;
208:     setPointLogs((prev) => [...prev, `🏆 СЕТ ЗА ${setWinnerPlayer.nameRu.toUpperCase()}!`]);
209: 
210:     // Check Match Won
211:     if (p1Sets === setsToWin || p2Sets === setsToWin) {
212:       const winnerId = p1Sets === setsToWin ? player1.id : player2.id;
213:       setIsMatchOver(true);
214:       setMatchWinner(winnerId);
215:       setIsAutoPlaying(false);
216:       soundFx.playWinnerFanfare();
217: 
218:       const finalScore: MatchScore = {
219:         sets: updatedSets,
220:         winnerId,
221:         durationMinutes: 45 * updatedSets.length + Math.floor(Math.random() * 20),
222:         stats,
223:       };
224: 
225:       onMatchFinished(match.id, winnerId, finalScore);
226:     } else {
227:       // Start next set
228:       const nextSets = [...updatedSets, [0, 0]] as Array<[number, number]>;
229:       setSets(nextSets);
230:       setCurrentSetIdx((idx) => idx + 1);
231:     }
232:   };
233: 
234:   // Auto-play timer
235:   useEffect(() => {
236:     let timer: NodeJS.Timeout | null = null;
237:     if (isAutoPlaying && !isMatchOver) {
238:       timer = setInterval(() => {
239:         handlePlayNextPoint();
240:       }, autoPlaySpeed);
241:     }
242:     return () => {
243:       if (timer) clearInterval(timer);
244:     };
245:   }, [isAutoPlaying, isMatchOver, autoPlaySpeed, sets, currentSetIdx, currentGamePoints, inTiebreak, tiebreakScore, server]);
246: 
247:   const gameScoreFormatted = formatGameScore(currentGamePoints[0], currentGamePoints[1]);
248: 
249:   return (
250:     <div className="space-y-6 max-w-5xl mx-auto pb-12">
251:       {/* Top Bar with Back button & Mute */}
252:       <div className="flex items-center justify-between">
253:         <button
254:           onClick={onBackToBracket}
255:           className="px-3.5 py-2 rounded-xl bg-slate-900 hover:bg-slate-800 border border-slate-800 text-slate-300 hover:text-white text-xs font-semibold flex items-center gap-1.5 transition cursor-pointer"
256:         >
257:           <ArrowLeft className="w-4 h-4" />
258:           <span>К турнирной сетке</span>
259:         </button>
260: 
261:         <div className="flex items-center gap-3">
262:           <button
263:             onClick={() => {
264:               const muted = soundFx.toggleMute();
265:               setIsMuted(muted);
266:             }}
267:             className="p-2 rounded-xl bg-slate-900 border border-slate-800 text-slate-300 hover:text-white transition cursor-pointer"
268:             title={isMuted ? 'Включить звук' : 'Выключить звук'}
269:           >
270:             {isMuted ? <VolumeX className="w-4 h-4 text-rose-400" /> : <Volume2 className="w-4 h-4 text-emerald-400" />}
271:           </button>
272:         </div>
273:       </div>
274: 
275:       {/* Main Live Scoreboard */}
276:       <div className="bg-slate-900/95 border border-slate-800 rounded-3xl p-5 sm:p-7 shadow-2xl relative overflow-hidden backdrop-blur-md">
277:         <div className="flex items-center justify-between mb-4 border-b border-slate-800 pb-3">
278:           <div className="flex items-center gap-2">
279:             <span className="text-xs font-black uppercase px-2 py-0.5 rounded bg-emerald-500/20 text-emerald-300">
280:               {match.roundName}
281:             </span>
282:             <span className="text-xs text-slate-400">
283:               Покрытие: <strong className="text-white">{surface}</strong>
284:             </span>
285:           </div>
286: 
287:           <div className="text-xs font-mono text-slate-400">
288:             {isMatchOver ? 'Матч завершен' : inTiebreak ? '🔥 Тай-брейк' : `Сет ${currentSetIdx + 1}`}
289:           </div>
290:         </div>
291: 
292:         {/* Players Score Rows */}
293:         <div className="space-y-3">
294:           {/* Player 1 Row */}
295:           <div className={`flex items-center justify-between p-3.5 rounded-2xl transition ${
296:             matchWinner === player1.id ? 'bg-emerald-500/20 border border-emerald-500/40' : 'bg-slate-950/60'
297:           }`}>
298:             <div className="flex items-center gap-3 min-w-0">
299:               {server === 1 && !isMatchOver && (
300:                 <span className="text-xs animate-bounce" title="Подает">🎾</span>
301:               )}
302:               {match.seed1 && (
303:                 <span className="text-xs font-mono font-bold px-1.5 py-0.5 rounded bg-slate-800 text-amber-400">
304:                   [{match.seed1}]
305:                 </span>
306:               )}
307:               <span className="text-xl">{player1.flag}</span>
308:               <div className="truncate">
309:                 <div className="text-sm sm:text-base font-bold text-white truncate flex items-center gap-2">
310:                   <span>{player1.nameRu}</span>
311:                   <span className="text-xs text-slate-400 font-normal">#{player1.rank}</span>
312:                 </div>
313:               </div>
314:             </div>
315: 
316:             {/* Sets & Points */}
317:             <div className="flex items-center gap-2 sm:gap-3 shrink-0 font-mono">
318:               {sets.map((set, sIdx) => (
319:                 <div
320:                   key={sIdx}
321:                   className={`w-8 h-8 rounded-lg flex items-center justify-center text-sm font-black ${
322:                     set[0] > set[1] ? 'bg-emerald-500/30 text-emerald-300' : 'bg-slate-900 text-slate-400'
323:                   }`}
324:                 >
325:                   {set[0]}
326:                 </div>
327:               ))}
328: 
329:               {/* Live Point */}
330:               {!isMatchOver && (
