332:                   {inTiebreak ? tiebreakScore[0] : gameScoreFormatted[0]}
333:                 </div>
334:               )}
335:             </div>
336:           </div>
337: 
338:           {/* Player 2 Row */}
339:           <div className={`flex items-center justify-between p-3.5 rounded-2xl transition ${
340:             matchWinner === player2.id ? 'bg-emerald-500/20 border border-emerald-500/40' : 'bg-slate-950/60'
341:           }`}>
342:             <div className="flex items-center gap-3 min-w-0">
343:               {server === 2 && !isMatchOver && (
344:                 <span className="text-xs animate-bounce" title="Подает">🎾</span>
345:               )}
346:               {match.seed2 && (
347:                 <span className="text-xs font-mono font-bold px-1.5 py-0.5 rounded bg-slate-800 text-amber-400">
348:                   [{match.seed2}]
349:                 </span>
350:               )}
351:               <span className="text-xl">{player2.flag}</span>
352:               <div className="truncate">
353:                 <div className="text-sm sm:text-base font-bold text-white truncate flex items-center gap-2">
354:                   <span>{player2.nameRu}</span>
355:                   <span className="text-xs text-slate-400 font-normal">#{player2.rank}</span>
356:                 </div>
357:               </div>
358:             </div>
359: 
360:             {/* Sets & Points */}
361:             <div className="flex items-center gap-2 sm:gap-3 shrink-0 font-mono">
362:               {sets.map((set, sIdx) => (
363:                 <div
364:                   key={sIdx}
365:                   className={`w-8 h-8 rounded-lg flex items-center justify-center text-sm font-black ${
366:                     set[1] > set[0] ? 'bg-emerald-500/30 text-emerald-300' : 'bg-slate-900 text-slate-400'
367:                   }`}
368:                 >
369:                   {set[1]}
370:                 </div>
371:               ))}
372: 
373:               {/* Live Point */}
374:               {!isMatchOver && (
375:                 <div className="w-10 h-8 rounded-lg bg-emerald-500 text-slate-950 flex items-center justify-center text-sm font-black shadow-lg shadow-emerald-500/20">
376:                   {inTiebreak ? tiebreakScore[1] : gameScoreFormatted[1]}
377:                 </div>
378:               )}
379:             </div>
380:           </div>
381:         </div>
382:       </div>
383: 
384:       {/* 2.5D Tennis Court Simulation View */}
385:       <div className="relative w-full aspect-[16/9] sm:aspect-[21/9] bg-gradient-to-b from-blue-900/60 via-emerald-950/40 to-blue-950/80 rounded-3xl border-2 border-emerald-500/30 overflow-hidden shadow-2xl flex items-center justify-center p-4">
386:         {/* Court markings */}
387:         <div className="w-[85%] h-[80%] border-2 border-white/60 relative bg-emerald-700/30 backdrop-blur-xs">
388:           {/* Net */}
389:           <div className="absolute top-1/2 left-0 right-0 h-1 bg-white/90 shadow-md shadow-black flex items-center justify-center">
390:             <div className="w-full h-2 border-b border-dashed border-white/40" />
391:           </div>
392: 
393:           {/* Service Lines */}
394:           <div className="absolute top-[25%] left-0 right-0 h-0.5 bg-white/50" />
395:           <div className="absolute top-[75%] left-0 right-0 h-0.5 bg-white/50" />
396:           <div className="absolute top-[25%] bottom-[25%] left-1/2 w-0.5 bg-white/50" />
397: 
398:           {/* Player avatars on court */}
399:           <div className="absolute top-[8%] left-1/2 -translate-x-1/2 flex flex-col items-center">
400:             <div className="text-xl sm:text-2xl drop-shadow-md">🧍‍♂️</div>
401:             <span className="text-[10px] font-bold bg-slate-950/80 px-2 py-0.5 rounded text-white border border-slate-700">
402:               {player2.nameRu.split(' ')[1] || player2.nameRu}
403:             </span>
404:           </div>
405: 
406:           <div className="absolute bottom-[8%] left-1/2 -translate-x-1/2 flex flex-col items-center">
407:             <span className="text-[10px] font-bold bg-slate-950/80 px-2 py-0.5 rounded text-white border border-slate-700">
408:               {player1.nameRu.split(' ')[1] || player1.nameRu}
409:             </span>
410:             <div className="text-xl sm:text-2xl drop-shadow-md">🧍‍♂️</div>
411:           </div>
412: 
413:           {/* Animated Tennis Ball */}
414:           {isBallActive && (
415:             <div
416:               className="absolute w-3.5 h-3.5 rounded-full bg-lime-300 shadow-lg shadow-lime-400 border border-lime-100 transition-all duration-300 pointer-events-none -translate-x-1/2 -translate-y-1/2 animate-pulse"
417:               style={{ left: `${ballPos.x}%`, top: `${ballPos.y}%` }}
418:             />
