435: 
436:             <button
437:               onClick={() => setIsAutoPlaying(!isAutoPlaying)}
438:               className={`px-4 py-2.5 rounded-xl font-bold text-xs sm:text-sm transition flex items-center gap-2 shadow-lg cursor-pointer ${
439:                 isAutoPlaying
