445:               <span>{isAutoPlaying ? 'Пауза автоигры' : 'Автоигра'}</span>
446:             </button>
447:           </div>
448: 
449:           {/* Speed Selector */}
450:           <div className="flex items-center gap-1.5 bg-slate-950/80 p-1.5 rounded-xl border border-slate-800">
451:             <span className="text-[11px] text-slate-400 px-2">Скорость:</span>
452:             {[
453:               { label: '1x', speed: 900 },
454:               { label: '2x', speed: 450 },
455:               { label: '5x', speed: 150 },
456:             ].map((s) => (
457:               <button
458:                 key={s.label}
459:                 onClick={() => setAutoPlaySpeed(s.speed)}
460:                 className={`px-2.5 py-1 rounded-lg text-xs font-bold transition cursor-pointer ${
461:                   autoPlaySpeed === s.speed
462:                     ? 'bg-emerald-500 text-slate-950'
463:                     : 'text-slate-400 hover:text-white hover:bg-slate-800'
464:                 }`}
465:               >
