475:             <div>
476:               <div className="text-sm font-bold text-white">Матч завершен!</div>
477:               <div className="text-xs text-slate-300">
478:                 Победитель: <strong>{matchWinner === player1.id ? player1.nameRu : player2.nameRu}</strong>
479:               </div>
