129: export function generateTournamentDraw(
130:   template: Omit<Tournament, 'matches' | 'isCompleted' | 'currentRound' | 'championId' | 'runnerUpId'>,
131:   allPlayers: Player[],
132:   _isFirst: boolean = false
133: ): Tournament {
134:   const eligiblePlayers = allPlayers
135:     .filter((p) => p.tour === template.tour && !p.retired)
136:     .sort((a, b) => a.rank - b.rank);
137:   const tournamentPlayers = eligiblePlayers.slice(0, template.drawSize);
138:   const seededIndices = getStandardBracketSeeding(template.drawSize);
139:   const seededDraw = new Array<Player | undefined>(getBracketSize(template.drawSize));
140: 
141:   seededIndices.forEach((playerIndex, slot) => {
142:     seededDraw[slot] = tournamentPlayers[playerIndex];
143:   });
144: 
145:   const tournament: Tournament = {
146:     ...template,
147:     matches: createBracketMatches(template.id, template.drawSize, seededDraw),
148:     isCompleted: false,
149:     currentRound: 0,
150:   };
151:   resolveBracketByes(tournament);
152:   return tournament;
