155: export function repairTournamentBracket(tournament: Tournament, allPlayers: Player[]): Tournament {
156:   const totalRounds = getBracketRoundCount(tournament.drawSize);
157:   const bracketSize = getBracketSize(tournament.drawSize);
158:   const hasValidShape = Array.from({ length: totalRounds }, (_, round) => {
159:     const expectedCount = bracketSize / (2 ** (round + 1));
160:     return tournament.matches.filter((match) => match.round === round).length === expectedCount;
161:   }).every(Boolean);
162:   const oldMatches = new Map(tournament.matches.map((match) => [match.id, match]));
163:   const repaired = hasValidShape
164:     ? JSON.parse(JSON.stringify(tournament)) as Tournament
165:     : generateTournamentDraw(tournament, allPlayers);
166:   const eligiblePlayers = allPlayers
167:     .filter((player) => player.tour === repaired.tour && !player.retired)
168:     .sort((a, b) => a.rank - b.rank)
169:     .slice(0, repaired.drawSize);
170:   const eligibleById = new Map(eligiblePlayers.map((player) => [player.id, player]));
171:   const firstRound = repaired.matches
172:     .filter((match) => match.round === 0)
173:     .sort((a, b) => Number(a.id.split('-m').pop()) - Number(b.id.split('-m').pop()));
174:   const generatedFirstRound = generateTournamentDraw(repaired, allPlayers).matches
175:     .filter((match) => match.round === 0)
176:     .sort((a, b) => Number(a.id.split('-m').pop()) - Number(b.id.split('-m').pop()));
177:   const assigned = new Set<string>();
178:   let entrantCount = 0;
179: 
180:   // Keep the existing entrants and their positions, but never exceed the tournament's draw size.
181:   for (const match of firstRound) {
182:     const oldMatch = oldMatches.get(match.id);
183:     for (const slot of [1, 2] as const) {
184:       const playerId = slot === 1 ? oldMatch?.player1Id : oldMatch?.player2Id;
185:       if (!playerId || !eligibleById.has(playerId) || assigned.has(playerId) || entrantCount >= repaired.drawSize) {
186:         if (slot === 1) match.player1Id = null;
187:         else match.player2Id = null;
188:         continue;
189:       }
190:       if (slot === 1) {
191:         match.player1Id = playerId;
192:         match.seed1 = oldMatch?.seed1 || eligibleById.get(playerId)?.rank;
193:       } else {
194:         match.player2Id = playerId;
195:         match.seed2 = oldMatch?.seed2 || eligibleById.get(playerId)?.rank;
196:       }
197:       assigned.add(playerId);
198:       entrantCount++;
199:     }
200:   }
201: 
202:   // Add eligible players into their seeded positions first; remaining vacancies stay byes.
203:   for (const generated of generatedFirstRound) {
204:     const target = firstRound.find((match) => match.id === generated.id);
205:     if (!target) continue;
206:     for (const slot of [1, 2] as const) {
207:       const playerId = slot === 1 ? generated.player1Id : generated.player2Id;
208:       const isVacant = slot === 1 ? !target.player1Id : !target.player2Id;
209:       if (!isVacant || !playerId || assigned.has(playerId) || entrantCount >= repaired.drawSize) continue;
210:       if (slot === 1) {
211:         target.player1Id = playerId;
212:         target.seed1 = generated.seed1;
213:       } else {
214:         target.player2Id = playerId;
215:         target.seed2 = generated.seed2;
216:       }
217:       assigned.add(playerId);
218:       entrantCount++;
219:     }
220:   }
221:   for (const player of eligiblePlayers) {
222:     if (entrantCount >= repaired.drawSize) break;
223:     if (assigned.has(player.id)) continue;
224:     const vacant = firstRound.flatMap((match) => [
225:       { match, slot: 1 as const },
226:       { match, slot: 2 as const },
227:     ]).find(({ match, slot }) => slot === 1 ? !match.player1Id : !match.player2Id);
228:     if (!vacant) break;
229:     if (vacant.slot === 1) {
230:       vacant.match.player1Id = player.id;
231:       vacant.match.seed1 = player.rank;
232:     } else {
233:       vacant.match.player2Id = player.id;
234:       vacant.match.seed2 = player.rank;
235:     }
236:     assigned.add(player.id);
237:     entrantCount++;
238:   }
239: 
240:   for (let round = 0; round < totalRounds; round++) {
241:     const matches = repaired.matches.filter((match) => match.round === round)
242:       .sort((a, b) => Number(a.id.split('-m').pop()) - Number(b.id.split('-m').pop()));
243:     const nextMatches = repaired.matches.filter((match) => match.round === round + 1)
244:       .sort((a, b) => Number(a.id.split('-m').pop()) - Number(b.id.split('-m').pop()));
245:     matches.forEach((match, index) => {
246:       match.roundName = getRoundName(round, totalRounds);
247:       match.nextMatchId = round < totalRounds - 1 ? nextMatches[Math.floor(index / 2)]?.id : undefined;
248:       match.nextMatchSlot = round < totalRounds - 1 ? (index % 2 === 0 ? 1 : 2) : undefined;
249:       match.isCompleted = false;
250:       match.winnerId = undefined;
251:       match.score = undefined;
252:     });
253:   }
254:   repaired.isCompleted = false;
255:   repaired.championId = undefined;
256:   repaired.runnerUpId = undefined;
257:   repaired.currentRound = 0;
258: 
259:   // Restore results only when the exact participants in that match are unchanged.
260:   const restoreCompatibleResults = (round: number) => {
261:     for (const match of repaired.matches.filter((candidate) => candidate.round === round)) {
262:       const oldMatch = oldMatches.get(match.id);
263:       if (
264:         oldMatch?.isCompleted && oldMatch.winnerId &&
265:         oldMatch.player1Id === match.player1Id && oldMatch.player2Id === match.player2Id &&
266:         match.player1Id && match.player2Id &&
267:         (oldMatch.winnerId === match.player1Id || oldMatch.winnerId === match.player2Id)
268:       ) {
269:         match.isCompleted = true;
270:         match.winnerId = oldMatch.winnerId;
271:         match.score = oldMatch.score;
272:       }
273:     }
274:   };
275:   restoreCompatibleResults(0);
276:   resolveBracketByes(repaired);
277:   for (let round = 1; round < totalRounds; round++) {
278:     restoreCompatibleResults(round);
279:     resolveBracketByes(repaired);
280:   }
281:   repaired.currentRound = repaired.matches.find((match) => !match.isCompleted)?.round ?? totalRounds;
282:   return repaired;
283: }
