314: export function advanceTournamentMatch(
315:   tournament: Tournament,
316:   matchId: string,
317:   winnerId: string,
318:   players: Player[]
319: ): { updatedTournament: Tournament; updatedPlayers: Player[] } {
320:   const updatedTournament = JSON.parse(JSON.stringify(tournament)) as Tournament;
321:   const match = updatedTournament.matches.find((m) => m.id === matchId);
322:   if (
323:     !match || match.isCompleted ||
324:     (match.player1Id !== winnerId && match.player2Id !== winnerId) ||
325:     !match.player1Id || !match.player2Id
326:   ) {
327:     return { updatedTournament, updatedPlayers: players };
328:   }
329: 
330:   match.isCompleted = true;
331:   match.winnerId = winnerId;
332: 
333:   // Propagate to next match
334:   if (match.nextMatchId) {
335:     const nextMatch = updatedTournament.matches.find((m) => m.id === match.nextMatchId);
336:     if (nextMatch) {
337:       if (match.nextMatchSlot === 1) {
338:         nextMatch.player1Id = winnerId;
339:         const winnerObj = players.find((p) => p.id === winnerId);
340:         if (winnerObj && winnerObj.rank <= 32) nextMatch.seed1 = winnerObj.rank;
341:       } else {
342:         nextMatch.player2Id = winnerId;
343:         const winnerObj = players.find((p) => p.id === winnerId);
344:         if (winnerObj && winnerObj.rank <= 32) nextMatch.seed2 = winnerObj.rank;
345:       }
346:     }
347:   }
348: 
349:   resolveBracketByes(updatedTournament);
350:   const totalRounds = getBracketRoundCount(updatedTournament.drawSize);
351:   const nextUnplayedRound = updatedTournament.matches.find((candidate) => !candidate.isCompleted)?.round;
352:   updatedTournament.currentRound = nextUnplayedRound ?? totalRounds;
353: 
354:   // Update player form / match records
355:   const updatedPlayers = players.map((p) => {
356:     if (p.id === winnerId) {
357:       return {
358:         ...p,
359:         matchesWon: p.matchesWon + 1,
360:         form: Math.min(1.25, p.form + 0.01),
361:       };
362:     }
363:     const loserId = match.player1Id === winnerId ? match.player2Id : match.player1Id;
364:     if (p.id === loserId) {
365:       return {
366:         ...p,
367:         matchesLost: p.matchesLost + 1,
368:         form: Math.max(0.75, p.form - 0.015),
369:       };
370:     }
371:     return p;
372:   });
373: 
374:   return { updatedTournament, updatedPlayers };
375: }
