function resolveBracketByes(tournament: Tournament): void {
  const totalRounds = getBracketRoundCount(tournament.drawSize);
  for (let round = 0; round < totalRounds; round++) {
    const matches = tournament.matches.filter((match) => match.round === round);
    for (const match of matches) {
      if (round > 0) {
        const previousRound = tournament.matches.filter((candidate) => candidate.round === round - 1);
        const childMatches = previousRound.filter((child) => child.nextMatchId === match.id);
        if (childMatches.length !== 2 || childMatches.some((child) => !child.isCompleted)) continue;
        const [first, second] = childMatches.sort((a, b) => (a.nextMatchSlot || 0) - (b.nextMatchSlot || 0));
        match.player1Id = first.winnerId || null;
        match.player2Id = second.winnerId || null;
        match.seed1 = first.winnerId === first.player1Id ? first.seed1 : first.winnerId === first.player2Id ? first.seed2 : undefined;
        match.seed2 = second.winnerId === second.player1Id ? second.seed1 : second.winnerId === second.player2Id ? second.seed2 : undefined;
      }

      if (!match.player1Id || !match.player2Id) {
        match.isCompleted = true;
        match.winnerId = match.player1Id || match.player2Id || undefined;
        match.score = undefined;
      } else if (match.isCompleted && !match.score) {
        // A former bye is now a real match after a bracket repair or player fill-in.
        match.isCompleted = false;
        match.winnerId = undefined;
      }
    }
  }

  const finalRound = totalRounds - 1;
  const finalMatch = tournament.matches.find((match) => match.round === finalRound);
  if (finalMatch?.isCompleted && finalMatch.winnerId) {
    tournament.isCompleted = true;
    tournament.championId = finalMatch.winnerId;
    const loserId = finalMatch.player1Id === finalMatch.winnerId ? finalMatch.player2Id : finalMatch.player1Id;
    tournament.runnerUpId = loserId || undefined;
  }
}

