352: export function advanceTournamentMatch(
353:   tournament: Tournament,
354:   matchId: string,
355:   winnerId: string,
356:   players: Player[]
357: ): { updatedTournament: Tournament; updatedPlayers: Player[] } {
358:   const updatedTournament = JSON.parse(JSON.stringify(tournament)) as Tournament;
359:   const match = updatedTournament.matches.find((m) => m.id === matchId);
360:   if (
361:     !match || match.isCompleted ||
362:     (match.player1Id !== winnerId && match.player2Id !== winnerId) ||
363:     !match.player1Id || !match.player2Id
364:   ) {
365:     return { updatedTournament, updatedPlayers: players };
366:   }
367: 
368:   match.isCompleted = true;
369:   match.winnerId = winnerId;
370: 
371:   // Propagate to next match
372:   if (match.nextMatchId) {
373:     const nextMatch = updatedTournament.matches.find((m) => m.id === match.nextMatchId);
374:     if (nextMatch) {
375:       if (match.nextMatchSlot === 1) {
376:         nextMatch.player1Id = winnerId;
377:         const winnerObj = players.find((p) => p.id === winnerId);
378:         if (winnerObj && winnerObj.rank <= 32) nextMatch.seed1 = winnerObj.rank;
379:       } else {
380:         nextMatch.player2Id = winnerId;
381:         const winnerObj = players.find((p) => p.id === winnerId);
382:         if (winnerObj && winnerObj.rank <= 32) nextMatch.seed2 = winnerObj.rank;
383:       }
384:     }
385:   }
386: 
387:   resolveBracketByes(updatedTournament);
388:   const totalRounds = getBracketRoundCount(updatedTournament.drawSize);
389:   const nextUnplayedRound = updatedTournament.matches.find((candidate) => !candidate.isCompleted)?.round;
390:   updatedTournament.currentRound = nextUnplayedRound ?? totalRounds;
391: 
392:   // Update player form / match records
393:   const updatedPlayers = players.map((p) => {
394:     if (p.id === winnerId) {
395:       return {
396:         ...p,
397:         matchesWon: p.matchesWon + 1,
398:         form: Math.min(1.25, p.form + 0.01),
399:       };
400:     }
401:     const loserId = match.player1Id === winnerId ? match.player2Id : match.player1Id;
402:     if (p.id === loserId) {
403:       return {
404:         ...p,
405:         matchesLost: p.matchesLost + 1,
406:         form: Math.max(0.75, p.form - 0.015),
407:       };
408:     }
409:     return p;
410:   });
411: 
412:   return { updatedTournament, updatedPlayers };
413: }
