517: export function recalculateRankings(players: Player[]): Player[] {
518:   const atp = players.filter((p) => p.tour === 'ATP' && !p.retired);
519:   const wta = players.filter((p) => p.tour === 'WTA' && !p.retired);
520:   const retired = players.filter((p) => p.retired);
521: 
522:   const sortTour = (list: Player[]) => {
523:     list.sort((a, b) => b.points - a.points || a.rank - b.rank);
524:     return list.map((p, idx) => ({
525:       ...p,
526:       previousRank: p.rank,
527:       rank: idx + 1,
528:     }));
529:   };
530: 
531:   const rankedAtp = sortTour(atp);
532:   const rankedWta = sortTour(wta);
533: 
534:   return [...rankedAtp, ...rankedWta, ...retired];
535: }
