537: export function simulateEntireTournament(
538:   tournament: Tournament,
539:   players: Player[]
540: ): { completedTournament: Tournament; updatedPlayers: Player[] } {
541:   let currTournament = JSON.parse(JSON.stringify(tournament)) as Tournament;
542:   let currPlayers = [...players];
543: 
544:   const totalRounds = getBracketRoundCount(currTournament.drawSize);
545: 
546:   for (let r = 0; r < totalRounds; r++) {
547:     const roundMatches = currTournament.matches.filter((m) => m.round === r && !m.isCompleted);
548:     for (const match of roundMatches) {
549:       if (match.player1Id && match.player2Id) {
550:         const p1 = currPlayers.find((p) => p.id === match.player1Id);
551:         const p2 = currPlayers.find((p) => p.id === match.player2Id);
552: 
553:         if (p1 && p2) {
554:           const sim = simulateFullMatch(p1, p2, currTournament.surface, currTournament.setsToWin);
555:           const currentMatch = currTournament.matches.find((candidate) => candidate.id === match.id);
556:           if (currentMatch) currentMatch.score = sim.score;
557:           const adv = advanceTournamentMatch(currTournament, match.id, sim.winnerId, currPlayers);
558:           currTournament = adv.updatedTournament;
559:           currPlayers = adv.updatedPlayers;
560:         }
561:       }
562:     }
563:   }
564: 
565:   currPlayers = finalizeTournamentAndDistributePoints(currTournament, currPlayers);
566:   return { completedTournament: currTournament, updatedPlayers: currPlayers };
567: }

