415: export function finalizeTournamentAndDistributePoints(
416:   tournament: Tournament,
417:   players: Player[]
418: ): Player[] {
419:   if (!tournament.isCompleted) return players;
420: 
421:   const pointsMap = new Map<string, { points: number; prize: number; wonTitle: boolean }>();
422: 
423:   const totalRounds = getBracketRoundCount(tournament.drawSize);
424:   const firstRoundPoints: Record<number, number> = {
425:     2: tournament.pointsSemi,
426:     3: tournament.pointsQuarter,
427:     4: tournament.pointsR16,
428:     5: tournament.pointsR32,
429:     6: tournament.pointsR64,
430:     7: tournament.pointsR128,
431:   };
432:   const awardByRoundsRemaining: Record<number, { points: number; prizeRate: number }> = {
433:     2: { points: tournament.pointsSemi, prizeRate: 0.06 },
434:     3: { points: tournament.pointsQuarter, prizeRate: 0.035 },
435:     4: { points: tournament.pointsR16, prizeRate: 0.018 },
436:     5: { points: tournament.pointsR32, prizeRate: 0.009 },
437:     6: { points: tournament.pointsR64, prizeRate: 0.004 },
438:     7: { points: tournament.pointsR128, prizeRate: 0.002 },
439:   };
440: 
441:   tournament.matches.forEach((m) => {
442:     if (!m.isCompleted || !m.player1Id || !m.player2Id || !m.winnerId) return;
443:     const loserId = m.winnerId === m.player1Id ? m.player2Id : m.player1Id;
444:     if (m.round === totalRounds - 1) {
445:       pointsMap.set(m.winnerId, {
446:         points: tournament.pointsWinner,
447:         prize: Math.round(tournament.prizeMoneyPool * 0.22),
448:         wonTitle: true,
449:       });
450:       pointsMap.set(loserId, {
451:         points: tournament.pointsFinalist,
452:         prize: Math.round(tournament.prizeMoneyPool * 0.12),
453:         wonTitle: false,
454:       });
455:       return;
456:     }
457: 
458:     if (pointsMap.has(loserId)) return;
459:     const award = awardByRoundsRemaining[totalRounds - m.round];
460:     if (award) {
461:       pointsMap.set(loserId, {
462:         points: award.points,
463:         prize: Math.round(tournament.prizeMoneyPool * award.prizeRate),
464:         wonTitle: false,
465:       });
466:     }
467:   });
468: 
469:   const updatedPlayers = players.map((p) => {
470:     if (p.tour !== tournament.tour) return p;
471: 
472:     const tourneyPointsHistory = p.tournamentPoints || {};
473:     // Defended points = points earned at this specific tournament in the previous season edition
474:     const defendedPoints = tourneyPointsHistory[tournament.id] || 0;
475: 
476:     let earnedPoints = 0;
477:     let prize = 0;
478:     let wonTitle = false;
479: 
480:     if (pointsMap.has(p.id)) {
481:       const award = pointsMap.get(p.id)!;
482:       earnedPoints = award.points;
483:       prize = award.prize;
484:       wonTitle = award.wonTitle;
485:     } else {
486:       const playedInTournament = tournament.matches.some(
487:         (m) => m.player1Id === p.id || m.player2Id === p.id
488:       );
489:       if (playedInTournament) {
490:         earnedPoints = firstRoundPoints[totalRounds] || 0;
491:       }
492:     }
493: 
494:     const updatedTourneyPoints = {
495:       ...tourneyPointsHistory,
496:       [tournament.id]: earnedPoints,
497:     };
498: 
499:     const netPointsChange = earnedPoints - defendedPoints;
500:     const newPoints = Math.max(0, p.points + netPointsChange);
501: 
502:     return {
503:       ...p,
504:       previousPoints: p.points,
505:       points: newPoints,
506:       tournamentPoints: updatedTourneyPoints,
507:       prizeMoney: p.prizeMoney + prize,
508:       titles: wonTitle ? p.titles + 1 : p.titles,
509:       careerTitles: wonTitle ? p.careerTitles + 1 : p.careerTitles,
510:       grandSlams: wonTitle && tournament.category === 'Grand Slam' ? p.grandSlams + 1 : p.grandSlams,
511:     };
512:   });
513: 
514:   return recalculateRankings(updatedPlayers);
515: }
