164:   _isFirst: boolean = false
165: ): Tournament {
166:   const eligiblePlayers = allPlayers
167:     .filter((p) => p.tour === template.tour && !p.retired)
168:     .sort((a, b) => a.rank - b.rank);
169:   const tournamentPlayers = eligiblePlayers.slice(0, template.drawSize);
170:   const seededIndices = getStandardBracketSeeding(template.drawSize);
171:   const seededDraw = new Array<Player | undefined>(getBracketSize(template.drawSize));
172: 
173:   seededIndices.forEach((playerIndex, slot) => {
174:     seededDraw[slot] = tournamentPlayers[playerIndex];
175:   });
176: 
177:   const tournament: Tournament = {
178:     ...template,
179:     matches: createBracketMatches(template.id, template.drawSize, seededDraw),
180:     isCompleted: false,
181:     currentRound: 0,
182:   };
