187: export function repairTournamentBracket(tournament: Tournament, allPlayers: Player[]): Tournament {
188:   const totalRounds = getBracketRoundCount(tournament.drawSize);
189:   const bracketSize = getBracketSize(tournament.drawSize);
190:   const hasValidShape = Array.from({ length: totalRounds }, (_, round) => {
191:     const expectedCount = bracketSize / (2 ** (round + 1));
192:     return tournament.matches.filter((match) => match.round === round).length === expectedCount;
193:   }).every(Boolean);
194:   const oldMatches = new Map(tournament.matches.map((match) => [match.id, match]));
195:   const repaired = hasValidShape
196:     ? JSON.parse(JSON.stringify(tournament)) as Tournament
197:     : generateTournamentDraw(tournament, allPlayers);
198:   const eligiblePlayers = allPlayers
199:     .filter((player) => player.tour === repaired.tour && !player.retired)
200:     .sort((a, b) => a.rank - b.rank)
201:     .slice(0, repaired.drawSize);
202:   const eligibleById = new Map(eligiblePlayers.map((player) => [player.id, player]));
203:   const firstRound = repaired.matches
204:     .filter((match) => match.round === 0)
205:     .sort((a, b) => Number(a.id.split('-m').pop()) - Number(b.id.split('-m').pop()));
206:   const generatedFirstRound = generateTournamentDraw(repaired, allPlayers).matches
207:     .filter((match) => match.round === 0)
208:     .sort((a, b) => Number(a.id.split('-m').pop()) - Number(b.id.split('-m').pop()));
209:   const assigned = new Set<string>();
210:   let entrantCount = 0;
211: 
212:   // Keep the existing entrants and their positions, but never exceed the tournament's draw size.
213:   for (const match of firstRound) {
214:     const oldMatch = oldMatches.get(match.id);
215:     for (const slot of [1, 2] as const) {
216:       const playerId = slot === 1 ? oldMatch?.player1Id : oldMatch?.player2Id;
217:       if (!playerId || !eligibleById.has(playerId) || assigned.has(playerId) || entrantCount >= repaired.drawSize) {
218:         if (slot === 1) match.player1Id = null;
219:         else match.player2Id = null;
220:         continue;
221:       }
222:       if (slot === 1) {
223:         match.player1Id = playerId;
224:         match.seed1 = oldMatch?.seed1 || eligibleById.get(playerId)?.rank;
225:       } else {
226:         match.player2Id = playerId;
227:         match.seed2 = oldMatch?.seed2 || eligibleById.get(playerId)?.rank;
228:       }
229:       assigned.add(playerId);
230:       entrantCount++;
231:     }
232:   }
233: 
234:   // Add eligible players into their seeded positions first; remaining vacancies stay byes.
235:   for (const generated of generatedFirstRound) {
236:     const target = firstRound.find((match) => match.id === generated.id);
237:     if (!target) continue;
238:     for (const slot of [1, 2] as const) {
239:       const playerId = slot === 1 ? generated.player1Id : generated.player2Id;
240:       const isVacant = slot === 1 ? !target.player1Id : !target.player2Id;
241:       if (!isVacant || !playerId || assigned.has(playerId) || entrantCount >= repaired.drawSize) continue;
242:       if (slot === 1) {
243:         target.player1Id = playerId;
244:         target.seed1 = generated.seed1;
245:       } else {
246:         target.player2Id = playerId;
247:         target.seed2 = generated.seed2;
248:       }
249:       assigned.add(playerId);
250:       entrantCount++;
251:     }
252:   }
253:   for (const player of eligiblePlayers) {
254:     if (entrantCount >= repaired.drawSize) break;
255:     if (assigned.has(player.id)) continue;
256:     const vacant = firstRound.flatMap((match) => [
257:       { match, slot: 1 as const },
258:       { match, slot: 2 as const },
259:     ]).find(({ match, slot }) => slot === 1 ? !match.player1Id : !match.player2Id);
260:     if (!vacant) break;
261:     if (vacant.slot === 1) {
262:       vacant.match.player1Id = player.id;
263:       vacant.match.seed1 = player.rank;
264:     } else {
265:       vacant.match.player2Id = player.id;
266:       vacant.match.seed2 = player.rank;
267:     }
268:     assigned.add(player.id);
269:     entrantCount++;
270:   }
271: 
272:   for (let round = 0; round < totalRounds; round++) {
273:     const matches = repaired.matches.filter((match) => match.round === round)
274:       .sort((a, b) => Number(a.id.split('-m').pop()) - Number(b.id.split('-m').pop()));
275:     const nextMatches = repaired.matches.filter((match) => match.round === round + 1)
276:       .sort((a, b) => Number(a.id.split('-m').pop()) - Number(b.id.split('-m').pop()));
277:     matches.forEach((match, index) => {
278:       match.roundName = getRoundName(round, totalRounds);
279:       match.nextMatchId = round < totalRounds - 1 ? nextMatches[Math.floor(index / 2)]?.id : undefined;
280:       match.nextMatchSlot = round < totalRounds - 1 ? (index % 2 === 0 ? 1 : 2) : undefined;
281:       if (round > 0) {
282:         match.player1Id = null;
283:         match.player2Id = null;
284:         match.seed1 = undefined;
285:         match.seed2 = undefined;
286:       }
287:       match.isCompleted = false;
288:       match.winnerId = undefined;
289:       match.score = undefined;
290:     });
291:   }
292:   repaired.isCompleted = false;
293:   repaired.championId = undefined;
294:   repaired.runnerUpId = undefined;
295:   repaired.currentRound = 0;
296: 
297:   // Restore results only when the exact participants in that match are unchanged.
298:   const restoreCompatibleResults = (round: number) => {
299:     for (const match of repaired.matches.filter((candidate) => candidate.round === round)) {
300:       const oldMatch = oldMatches.get(match.id);
301:       if (
302:         oldMatch?.isCompleted && oldMatch.winnerId &&
303:         oldMatch.player1Id === match.player1Id && oldMatch.player2Id === match.player2Id &&
304:         match.player1Id && match.player2Id &&
305:         (oldMatch.winnerId === match.player1Id || oldMatch.winnerId === match.player2Id)
306:       ) {
307:         match.isCompleted = true;
308:         match.winnerId = oldMatch.winnerId;
309:         match.score = oldMatch.score;
310:       }
311:     }
312:   };
313:   restoreCompatibleResults(0);
314:   resolveBracketByes(repaired);
315:   for (let round = 1; round < totalRounds; round++) {
316:     restoreCompatibleResults(round);
317:     resolveBracketByes(repaired);
318:   }
319:   repaired.currentRound = repaired.matches.find((match) => !match.isCompleted)?.round ?? totalRounds;
320:   return repaired;
321: }
