415: export function finalizeTournamentAndDistributePoints(
416:   tournament: Tournament,
417:   players: Player[]
418: ): { updatedTournament: Tournament; updatedPlayers: Player[] } {
419:   if (!tournament.isCompleted || tournament.pointsDistributed) {
420:     return { updatedTournament: tournament, updatedPlayers: players };
421:   }
422: 
423:   const pointsMap = new Map<string, { points: number; prize: number; wonTitle: boolean }>();
424: 
425:   const totalRounds = getBracketRoundCount(tournament.drawSize);
426:   const firstRoundPoints: Record<number, number> = {
427:     2: tournament.pointsSemi,
428:     3: tournament.pointsQuarter,
429:     4: tournament.pointsR16,
430:     5: tournament.pointsR32,
431:     6: tournament.pointsR64,
432:     7: tournament.pointsR128,
433:   };
434:   const awardByRoundsRemaining: Record<number, { points: number; prizeRate: number }> = {
435:     2: { points: tournament.pointsSemi, prizeRate: 0.06 },
436:     3: { points: tournament.pointsQuarter, prizeRate: 0.035 },
437:     4: { points: tournament.pointsR16, prizeRate: 0.018 },
438:     5: { points: tournament.pointsR32, prizeRate: 0.009 },
439:     6: { points: tournament.pointsR64, prizeRate: 0.004 },
440:     7: { points: tournament.pointsR128, prizeRate: 0.002 },
441:   };
442: 
443:   tournament.matches.forEach((m) => {
444:     if (!m.isCompleted || !m.player1Id || !m.player2Id || !m.winnerId) return;
445:     const loserId = m.winnerId === m.player1Id ? m.player2Id : m.player1Id;
446:     if (m.round === totalRounds - 1) {
447:       pointsMap.set(m.winnerId, {
448:         points: tournament.pointsWinner,
449:         prize: Math.round(tournament.prizeMoneyPool * 0.22),
450:         wonTitle: true,
451:       });
452:       pointsMap.set(loserId, {
453:         points: tournament.pointsFinalist,
454:         prize: Math.round(tournament.prizeMoneyPool * 0.12),
455:         wonTitle: false,
456:       });
457:       return;
458:     }
459: 
460:     if (pointsMap.has(loserId)) return;
461:     const award = awardByRoundsRemaining[totalRounds - m.round];
462:     if (award) {
463:       pointsMap.set(loserId, {
464:         points: award.points,
465:         prize: Math.round(tournament.prizeMoneyPool * award.prizeRate),
466:         wonTitle: false,
467:       });
468:     }
469:   });
470: 
471:   const updatedPlayers = players.map((p) => {
472:     if (p.tour !== tournament.tour) return p;
473: 
474:     const tourneyPointsHistory = p.tournamentPoints || {};
475:     // Defended points = points earned at this specific tournament in the previous season edition
476:     const defendedPoints = tourneyPointsHistory[tournament.id] || 0;
477: 
478:     let earnedPoints = 0;
479:     let prize = 0;
480:     let wonTitle = false;
481: 
482:     if (pointsMap.has(p.id)) {
483:       const award = pointsMap.get(p.id)!;
484:       earnedPoints = award.points;
485:       prize = award.prize;
486:       wonTitle = award.wonTitle;
487:     } else {
488:       const playedInTournament = tournament.matches.some(
489:         (m) => m.player1Id === p.id || m.player2Id === p.id
490:       );
491:       if (playedInTournament) {
492:         earnedPoints = firstRoundPoints[totalRounds] || 0;
493:       }
494:     }
495: 
496:     const updatedTourneyPoints = {
497:       ...tourneyPointsHistory,
498:       [tournament.id]: earnedPoints,
499:     };
500: 
501:     const netPointsChange = earnedPoints - defendedPoints;
502:     const newPoints = Math.max(0, p.points + netPointsChange);
503: 
504:     return {
505:       ...p,
506:       previousPoints: p.points,
507:       points: newPoints,
508:       tournamentPoints: updatedTourneyPoints,
509:       prizeMoney: p.prizeMoney + prize,
510:       titles: wonTitle ? p.titles + 1 : p.titles,
511:       careerTitles: wonTitle ? p.careerTitles + 1 : p.careerTitles,
512:       grandSlams: wonTitle && tournament.category === 'Grand Slam' ? p.grandSlams + 1 : p.grandSlams,
513:     };
514:   });
515: 
516:   return {
517:     updatedTournament: { ...tournament, pointsDistributed: true },
518:     updatedPlayers: recalculateRankings(updatedPlayers),
519:   };
520: }
