522: export function recalculateRankings(players: Player[]): Player[] {
523:   const atp = players.filter((p) => p.tour === 'ATP' && !p.retired);
524:   const wta = players.filter((p) => p.tour === 'WTA' && !p.retired);
525:   const retired = players.filter((p) => p.retired);
526: 
527:   const sortTour = (list: Player[]) => {
528:     list.sort((a, b) => b.points - a.points || a.rank - b.rank);
529:     return list.map((p, idx) => ({
530:       ...p,
531:       previousRank: p.rank,
532:       rank: idx + 1,
533:     }));
534:   };
535: 
536:   const rankedAtp = sortTour(atp);
537:   const rankedWta = sortTour(wta);
538: 
539:   return [...rankedAtp, ...rankedWta, ...retired];
540: }
