542: export function simulateEntireTournament(
543:   tournament: Tournament,
544:   players: Player[]
545: ): { completedTournament: Tournament; updatedPlayers: Player[] } {
546:   let currTournament = JSON.parse(JSON.stringify(tournament)) as Tournament;
547:   let currPlayers = [...players];
548: 
549:   const totalRounds = getBracketRoundCount(currTournament.drawSize);
550: 
551:   for (let r = 0; r < totalRounds; r++) {
552:     const roundMatches = currTournament.matches.filter((m) => m.round === r && !m.isCompleted);
553:     for (const match of roundMatches) {
554:       if (match.player1Id && match.player2Id) {
555:         const p1 = currPlayers.find((p) => p.id === match.player1Id);
556:         const p2 = currPlayers.find((p) => p.id === match.player2Id);
557: 
558:         if (p1 && p2) {
559:           const sim = simulateFullMatch(p1, p2, currTournament.surface, currTournament.setsToWin);
560:           const currentMatch = currTournament.matches.find((candidate) => candidate.id === match.id);
561:           if (currentMatch) currentMatch.score = sim.score;
562:           const adv = advanceTournamentMatch(currTournament, match.id, sim.winnerId, currPlayers);
563:           currTournament = adv.updatedTournament;
564:           currPlayers = adv.updatedPlayers;
565:         }
566:       }
567:     }
568:   }
569: 
570:   const finalized = finalizeTournamentAndDistributePoints(currTournament, currPlayers);
571:   return { completedTournament: finalized.updatedTournament, updatedPlayers: finalized.updatedPlayers };
572: }

