91: function resolveBracketByes(tournament: Tournament): void {
92:   const totalRounds = getBracketRoundCount(tournament.drawSize);
93:   for (let round = 0; round < totalRounds; round++) {
94:     const matches = tournament.matches.filter((match) => match.round === round);
95:     for (const match of matches) {
96:       if (round === 0) {
97:         if (!match.player1Id || !match.player2Id) {
98:           match.isCompleted = true;
99:           match.winnerId = match.player1Id || match.player2Id || undefined;
100:           match.score = undefined;
101:         } else if (match.isCompleted && (!match.winnerId || ![match.player1Id, match.player2Id].includes(match.winnerId))) {
102:           match.isCompleted = false;
103:           match.winnerId = undefined;
104:           match.score = undefined;
105:         }
106:         continue;
107:       }
108: 
109:       const childMatches = tournament.matches
110:         .filter((child) => child.round === round - 1 && child.nextMatchId === match.id)
111:         .sort((a, b) => (a.nextMatchSlot || 0) - (b.nextMatchSlot || 0));
112:       if (childMatches.length !== 2) continue;
113: 
114:       const [first, second] = childMatches;
115:       match.player1Id = first.isCompleted ? first.winnerId || null : null;
116:       match.player2Id = second.isCompleted ? second.winnerId || null : null;
117:       match.seed1 = first.isCompleted && first.winnerId === first.player1Id
118:         ? first.seed1
119:         : first.isCompleted && first.winnerId === first.player2Id ? first.seed2 : undefined;
120:       match.seed2 = second.isCompleted && second.winnerId === second.player1Id
121:         ? second.seed1
122:         : second.isCompleted && second.winnerId === second.player2Id ? second.seed2 : undefined;
123: 
124:       if (!first.isCompleted || !second.isCompleted) {
125:         match.isCompleted = false;
126:         match.winnerId = undefined;
127:         match.score = undefined;
128:         continue;
129:       }
130: 
131:       const participants = [match.player1Id, match.player2Id].filter((id): id is string => Boolean(id));
132:       if (participants.length < 2) {
133:         match.isCompleted = true;
134:         match.winnerId = participants[0];
135:         match.score = undefined;
136:       } else if (
137:         match.isCompleted &&
138:         (!match.score || !match.winnerId || !participants.includes(match.winnerId))
139:       ) {
140:         // A former bye is now a real match after a bracket repair or player fill-in.
141:         match.isCompleted = false;
142:         match.winnerId = undefined;
143:         match.score = undefined;
144:       }
145:     }
146:   }
147: 
148:   const finalMatch = tournament.matches.find((match) => match.round === totalRounds - 1);
149:   if (finalMatch?.isCompleted && finalMatch.winnerId) {
150:     tournament.isCompleted = true;
151:     tournament.championId = finalMatch.winnerId;
152:     const loserId = finalMatch.player1Id === finalMatch.winnerId ? finalMatch.player2Id : finalMatch.player1Id;
153:     tournament.runnerUpId = loserId || undefined;
154:   } else {
155:     tournament.isCompleted = false;
156:     tournament.championId = undefined;
157:     tournament.runnerUpId = undefined;
158:   }
159: }
