187: export function repairTournamentBracket(tournament: Tournament, allPlayers: Player[]): Tournament {
188:   const totalRounds = getBracketRoundCount(tournament.drawSize);
189:   const completedFinal = tournament.matches.find((match) => match.round === totalRounds - 1);
190:   if (
191:     tournament.isCompleted && completedFinal?.isCompleted && completedFinal.winnerId &&
192:     [completedFinal.player1Id, completedFinal.player2Id].includes(completedFinal.winnerId)
193:   ) {
194:     // Finished tournaments are historical records; ranking changes must not rewrite their draw/results.
195:     const preserved = JSON.parse(JSON.stringify(tournament)) as Tournament;
196:     const finalMatch = preserved.matches.find((match) => match.round === totalRounds - 1)!;
197:     preserved.championId = finalMatch.winnerId;
198:     preserved.runnerUpId = finalMatch.player1Id === finalMatch.winnerId
199:       ? finalMatch.player2Id || undefined
