205:   const bracketSize = getBracketSize(tournament.drawSize);
206:   const hasValidShape = Array.from({ length: totalRounds }, (_, round) => {
207:     const expectedCount = bracketSize / (2 ** (round + 1));
208:     return tournament.matches.filter((match) => match.round === round).length === expectedCount;
209:   }).every(Boolean);
210:   const oldMatches = new Map(tournament.matches.map((match) => [match.id, match]));
211:   const repaired = hasValidShape
212:     ? JSON.parse(JSON.stringify(tournament)) as Tournament
213:     : generateTournamentDraw(tournament, allPlayers);
214:   const eligiblePlayers = allPlayers
215:     .filter((player) => player.tour === repaired.tour && !player.retired)
216:     .sort((a, b) => a.rank - b.rank)
217:     .slice(0, repaired.drawSize);
218:   const eligibleById = new Map(eligiblePlayers.map((player) => [player.id, player]));
219:   const firstRound = repaired.matches
220:     .filter((match) => match.round === 0)
221:     .sort((a, b) => Number(a.id.split('-m').pop()) - Number(b.id.split('-m').pop()));
222:   const generatedFirstRound = generateTournamentDraw(repaired, allPlayers).matches
223:     .filter((match) => match.round === 0)
224:     .sort((a, b) => Number(a.id.split('-m').pop()) - Number(b.id.split('-m').pop()));
225:   const assigned = new Set<string>();
226:   let entrantCount = 0;
227: 
228:   // Keep the existing entrants and their positions, but never exceed the tournament's draw size.
229:   for (const match of firstRound) {
230:     const oldMatch = oldMatches.get(match.id);
231:     for (const slot of [1, 2] as const) {
232:       const playerId = slot === 1 ? oldMatch?.player1Id : oldMatch?.player2Id;
233:       if (!playerId || !eligibleById.has(playerId) || assigned.has(playerId) || entrantCount >= repaired.drawSize) {
234:         if (slot === 1) match.player1Id = null;
235:         else match.player2Id = null;
236:         continue;
237:       }
238:       if (slot === 1) {
239:         match.player1Id = playerId;
240:         match.seed1 = oldMatch?.seed1 || eligibleById.get(playerId)?.rank;
241:       } else {
242:         match.player2Id = playerId;
243:         match.seed2 = oldMatch?.seed2 || eligibleById.get(playerId)?.rank;
244:       }
245:       assigned.add(playerId);
246:       entrantCount++;
247:     }
248:   }
249: 
250:   // Add eligible players into their seeded positions first; remaining vacancies stay byes.
251:   for (const generated of generatedFirstRound) {
252:     const target = firstRound.find((match) => match.id === generated.id);
253:     if (!target) continue;
254:     for (const slot of [1, 2] as const) {
255:       const playerId = slot === 1 ? generated.player1Id : generated.player2Id;
256:       const isVacant = slot === 1 ? !target.player1Id : !target.player2Id;
257:       if (!isVacant || !playerId || assigned.has(playerId) || entrantCount >= repaired.drawSize) continue;
258:       if (slot === 1) {
259:         target.player1Id = playerId;
260:         target.seed1 = generated.seed1;
261:       } else {
262:         target.player2Id = playerId;
263:         target.seed2 = generated.seed2;
264:       }
265:       assigned.add(playerId);
266:       entrantCount++;
267:     }
268:   }
269:   for (const player of eligiblePlayers) {
270:     if (entrantCount >= repaired.drawSize) break;
271:     if (assigned.has(player.id)) continue;
272:     const vacant = firstRound.flatMap((match) => [
273:       { match, slot: 1 as const },
274:       { match, slot: 2 as const },
275:     ]).find(({ match, slot }) => slot === 1 ? !match.player1Id : !match.player2Id);
276:     if (!vacant) break;
277:     if (vacant.slot === 1) {
278:       vacant.match.player1Id = player.id;
279:       vacant.match.seed1 = player.rank;
280:     } else {
281:       vacant.match.player2Id = player.id;
282:       vacant.match.seed2 = player.rank;
283:     }
284:     assigned.add(player.id);
285:     entrantCount++;
