288:   for (let round = 0; round < totalRounds; round++) {
289:     const matches = repaired.matches.filter((match) => match.round === round)
290:       .sort((a, b) => Number(a.id.split('-m').pop()) - Number(b.id.split('-m').pop()));
291:     const nextMatches = repaired.matches.filter((match) => match.round === round + 1)
292:       .sort((a, b) => Number(a.id.split('-m').pop()) - Number(b.id.split('-m').pop()));
293:     matches.forEach((match, index) => {
294:       match.roundName = getRoundName(round, totalRounds);
295:       match.nextMatchId = round < totalRounds - 1 ? nextMatches[Math.floor(index / 2)]?.id : undefined;
296:       match.nextMatchSlot = round < totalRounds - 1 ? (index % 2 === 0 ? 1 : 2) : undefined;
297:       if (round > 0) {
298:         match.player1Id = null;
299:         match.player2Id = null;
300:         match.seed1 = undefined;
301:         match.seed2 = undefined;
302:       }
303:       match.isCompleted = false;
304:       match.winnerId = undefined;
305:       match.score = undefined;
306:     });
307:   }
308:   repaired.isCompleted = false;
309:   repaired.championId = undefined;
310:   repaired.runnerUpId = undefined;
311:   repaired.currentRound = 0;
312: 
313:   // Restore results only when the exact participants in that match are unchanged.
314:   const restoreCompatibleResults = (round: number) => {
315:     for (const match of repaired.matches.filter((candidate) => candidate.round === round)) {
316:       const oldMatch = oldMatches.get(match.id);
317:       if (
318:         oldMatch?.isCompleted && oldMatch.winnerId &&
319:         oldMatch.player1Id === match.player1Id && oldMatch.player2Id === match.player2Id &&
320:         match.player1Id && match.player2Id &&
321:         (oldMatch.winnerId === match.player1Id || oldMatch.winnerId === match.player2Id)
322:       ) {
323:         match.isCompleted = true;
324:         match.winnerId = oldMatch.winnerId;
325:         match.score = oldMatch.score;
326:       }
327:     }
328:   };
329:   restoreCompatibleResults(0);
330:   resolveBracketByes(repaired);
331:   for (let round = 1; round < totalRounds; round++) {
332:     restoreCompatibleResults(round);
333:     resolveBracketByes(repaired);
334:   }
335:   repaired.currentRound = repaired.matches.find((match) => !match.isCompleted)?.round ?? totalRounds;
336:   return repaired;
