368: export function advanceTournamentMatch(
369:   tournament: Tournament,
370:   matchId: string,
371:   winnerId: string,
372:   players: Player[]
373: ): { updatedTournament: Tournament; updatedPlayers: Player[] } {
374:   const updatedTournament = JSON.parse(JSON.stringify(tournament)) as Tournament;
375:   const match = updatedTournament.matches.find((m) => m.id === matchId);
376:   if (
377:     !match || match.isCompleted ||
378:     (match.player1Id !== winnerId && match.player2Id !== winnerId) ||
379:     !match.player1Id || !match.player2Id
380:   ) {
381:     return { updatedTournament, updatedPlayers: players };
382:   }
383: 
384:   match.isCompleted = true;
385:   match.winnerId = winnerId;
386: 
387:   // Propagate to next match
388:   if (match.nextMatchId) {
389:     const nextMatch = updatedTournament.matches.find((m) => m.id === match.nextMatchId);
390:     if (nextMatch) {
391:       if (match.nextMatchSlot === 1) {
392:         nextMatch.player1Id = winnerId;
393:         const winnerObj = players.find((p) => p.id === winnerId);
394:         if (winnerObj && winnerObj.rank <= 32) nextMatch.seed1 = winnerObj.rank;
395:       } else {
396:         nextMatch.player2Id = winnerId;
397:         const winnerObj = players.find((p) => p.id === winnerId);
398:         if (winnerObj && winnerObj.rank <= 32) nextMatch.seed2 = winnerObj.rank;
399:       }
400:     }
401:   }
402: 
403:   resolveBracketByes(updatedTournament);
404:   const totalRounds = getBracketRoundCount(updatedTournament.drawSize);
405:   const nextUnplayedRound = updatedTournament.matches.find((candidate) => !candidate.isCompleted)?.round;
406:   updatedTournament.currentRound = nextUnplayedRound ?? totalRounds;
407: 
408:   // Update player form / match records
409:   const updatedPlayers = players.map((p) => {
410:     if (p.id === winnerId) {
411:       return {
412:         ...p,
413:         matchesWon: p.matchesWon + 1,
414:         form: Math.min(1.25, p.form + 0.01),
415:       };
416:     }
417:     const loserId = match.player1Id === winnerId ? match.player2Id : match.player1Id;
418:     if (p.id === loserId) {
419:       return {
420:         ...p,
421:         matchesLost: p.matchesLost + 1,
422:         form: Math.max(0.75, p.form - 0.015),
423:       };
424:     }
425:     return p;
426:   });
427: 
428:   return { updatedTournament, updatedPlayers };
429: }
