431: export function finalizeTournamentAndDistributePoints(
432:   tournament: Tournament,
433:   players: Player[]
434: ): { updatedTournament: Tournament; updatedPlayers: Player[] } {
435:   if (!tournament.isCompleted || tournament.pointsDistributed) {
436:     return { updatedTournament: tournament, updatedPlayers: players };
437:   }
438: 
439:   const pointsMap = new Map<string, { points: number; prize: number; wonTitle: boolean }>();
440: 
441:   const totalRounds = getBracketRoundCount(tournament.drawSize);
442:   const firstRoundPoints: Record<number, number> = {
443:     2: tournament.pointsSemi,
444:     3: tournament.pointsQuarter,
445:     4: tournament.pointsR16,
446:     5: tournament.pointsR32,
447:     6: tournament.pointsR64,
448:     7: tournament.pointsR128,
449:   };
450:   const awardByRoundsRemaining: Record<number, { points: number; prizeRate: number }> = {
451:     2: { points: tournament.pointsSemi, prizeRate: 0.06 },
452:     3: { points: tournament.pointsQuarter, prizeRate: 0.035 },
453:     4: { points: tournament.pointsR16, prizeRate: 0.018 },
454:     5: { points: tournament.pointsR32, prizeRate: 0.009 },
455:     6: { points: tournament.pointsR64, prizeRate: 0.004 },
456:     7: { points: tournament.pointsR128, prizeRate: 0.002 },
457:   };
458: 
459:   tournament.matches.forEach((m) => {
460:     if (!m.isCompleted || !m.player1Id || !m.player2Id || !m.winnerId) return;
461:     const loserId = m.winnerId === m.player1Id ? m.player2Id : m.player1Id;
462:     if (m.round === totalRounds - 1) {
463:       pointsMap.set(m.winnerId, {
464:         points: tournament.pointsWinner,
465:         prize: Math.round(tournament.prizeMoneyPool * 0.22),
466:         wonTitle: true,
467:       });
468:       pointsMap.set(loserId, {
469:         points: tournament.pointsFinalist,
470:         prize: Math.round(tournament.prizeMoneyPool * 0.12),
471:         wonTitle: false,
472:       });
473:       return;
474:     }
475: 
476:     if (pointsMap.has(loserId)) return;
477:     const award = awardByRoundsRemaining[totalRounds - m.round];
478:     if (award) {
479:       pointsMap.set(loserId, {
480:         points: award.points,
481:         prize: Math.round(tournament.prizeMoneyPool * award.prizeRate),
482:         wonTitle: false,
483:       });
484:     }
485:   });
486: 
487:   const updatedPlayers = players.map((p) => {
488:     if (p.tour !== tournament.tour) return p;
489: 
490:     const tourneyPointsHistory = p.tournamentPoints || {};
491:     // Defended points = points earned at this specific tournament in the previous season edition
492:     const defendedPoints = tourneyPointsHistory[tournament.id] || 0;
493: 
494:     let earnedPoints = 0;
495:     let prize = 0;
496:     let wonTitle = false;
497: 
498:     if (pointsMap.has(p.id)) {
499:       const award = pointsMap.get(p.id)!;
500:       earnedPoints = award.points;
501:       prize = award.prize;
502:       wonTitle = award.wonTitle;
503:     } else {
504:       const playedInTournament = tournament.matches.some(
505:         (m) => m.player1Id === p.id || m.player2Id === p.id
506:       );
507:       if (playedInTournament) {
508:         earnedPoints = firstRoundPoints[totalRounds] || 0;
509:       }
510:     }
511: 
512:     const updatedTourneyPoints = {
513:       ...tourneyPointsHistory,
514:       [tournament.id]: earnedPoints,
515:     };
516: 
517:     const netPointsChange = earnedPoints - defendedPoints;
518:     const newPoints = Math.max(0, p.points + netPointsChange);
519: 
520:     return {
521:       ...p,
522:       previousPoints: p.points,
523:       points: newPoints,
524:       tournamentPoints: updatedTourneyPoints,
525:       prizeMoney: p.prizeMoney + prize,
526:       titles: wonTitle ? p.titles + 1 : p.titles,
527:       careerTitles: wonTitle ? p.careerTitles + 1 : p.careerTitles,
528:       grandSlams: wonTitle && tournament.category === 'Grand Slam' ? p.grandSlams + 1 : p.grandSlams,
529:     };
530:   });
531: 
532:   return {
533:     updatedTournament: { ...tournament, pointsDistributed: true },
534:     updatedPlayers: recalculateRankings(updatedPlayers),
535:   };
536: }
