538: export function recalculateRankings(players: Player[]): Player[] {
539:   const atp = players.filter((p) => p.tour === 'ATP' && !p.retired);
540:   const wta = players.filter((p) => p.tour === 'WTA' && !p.retired);
541:   const retired = players.filter((p) => p.retired);
