assert.equal(preserved.championId, completed.championId);
const completedOutcomes = (tournament: typeof completed) => tournament.matches
  .filter(m => m.isCompleted && m.player1Id && m.player2Id && m.winnerId)
  .map(({ id, player1Id, player2Id, winnerId, score }) => ({ id, player1Id, player2Id, winnerId, score }));
assert.deepEqual(completedOutcomes(preserved), completedOutcomes(completed), 'completed historical match outcomes must survive rank changes');

// A vacancy should be filled from the eligible list, and compatible earlier outcomes retained.
const partiallyPlayed = JSON.parse(JSON.stringify(completed)) as typeof completed;
const firstPlayed = partiallyPlayed.matches.find(m => m.round === 0 && m.player1Id && m.player2Id)!;
const earlierOutcome = { id: firstPlayed.id, player1Id: firstPlayed.player1Id, player2Id: firstPlayed.player2Id, winnerId: firstPlayed.winnerId, score: firstPlayed.score };
const expandedPool = all.filter(p => p.tour === base.tour).slice(0, 40);
const missingId = firstPlayed.player1Id!;
const repairedVacancy = repairTournamentBracket(partiallyPlayed, expandedPool.filter(p => p.id !== missingId));
assert.ok(!repairedVacancy.matches.some(m => m.round === 0 && (m.player1Id === missingId || m.player2Id === missingId)));
assert.ok(repairedVacancy.matches.some(m => m.round === 0 && m.player1Id && m.player2Id), 'vacancy repair should keep a valid draw');
const retainedEarlier = repairedVacancy.matches.find(m => m.id === earlierOutcome.id)!;
if (retainedEarlier.player1Id === earlierOutcome.player1Id && retainedEarlier.player2Id === earlierOutcome.player2Id) {
  assert.deepEqual({ id: retainedEarlier.id, player1Id: retainedEarlier.player1Id, player2Id: retainedEarlier.player2Id, winnerId: retainedEarlier.winnerId, score: retainedEarlier.score }, earlierOutcome);
}

// A completed match with an ineligible participant must not leave a stale winner/score behind.
const stale = JSON.parse(JSON.stringify(partiallyPlayed)) as typeof completed;
const staleMatch = stale.matches.find(m => m.round === 0 && m.player1Id && m.player2Id)!;
const removedId = staleMatch.player1Id!;
const replacementPool = expandedPool.map((p, index) => p.id === removedId ? { ...p, rank: 10000 + index } : p);
const repairedStale = repairTournamentBracket(stale, replacementPool);
const repairedStaleMatch = repairedStale.matches.find(m => m.id === staleMatch.id)!;
assert.notEqual(repairedStaleMatch.player1Id, removedId, 'ineligible entrant should be removed');
assert.ok(!repairedStaleMatch.isCompleted || repairedStaleMatch.winnerId === repairedStaleMatch.player1Id || repairedStaleMatch.winnerId === repairedStaleMatch.player2Id);
console.log('Bracket checks passed across draw sizes 16–128, vacancies, bye progression, completion, finalization idempotence, and result preservation.');

