const partiallyPlayed = JSON.parse(JSON.stringify(completed)) as typeof completed;
partiallyPlayed.isCompleted = false;
partiallyPlayed.championId = undefined;
partiallyPlayed.runnerUpId = undefined;
const playedMatches = partiallyPlayed.matches.filter(m => m.round === 0 && m.player1Id && m.player2Id);
const missingId = playedMatches[0].player1Id!;
const expandedPool = all.filter(p => p.tour === base.tour).slice(0, 40);
const repairedVacancy = repairTournamentBracket(partiallyPlayed, expandedPool.filter(p => p.id !== missingId));
assert.ok(!repairedVacancy.matches.some(m => m.round === 0 && (m.player1Id === missingId || m.player2Id === missingId)));
assert.ok(repairedVacancy.matches.some(m => m.round === 0 && m.player1Id && m.player2Id), 'vacancy repair should keep a valid draw');
for (const oldMatch of partiallyPlayed.matches.filter(m => m.isCompleted && m.player1Id && m.player2Id && m.winnerId)) {
  const repairedMatch = repairedVacancy.matches.find(m => m.id === oldMatch.id)!;
  if (repairedMatch.player1Id === oldMatch.player1Id && repairedMatch.player2Id === oldMatch.player2Id) {
    assert.equal(repairedMatch.winnerId, oldMatch.winnerId, `compatible winner retained for ${oldMatch.id}`);
    assert.deepEqual(repairedMatch.score, oldMatch.score, `compatible score retained for ${oldMatch.id}`);
  }
}

